quests[90110] = { id = 90110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Sammelt zeitverzerrte Proben", description = "Die Zerfaserung der Zeitlinie hat einige interessante Effekte auf Pflanzen und Gestein. Wir würden sie gerne untersuchen.\n\nSammelt zeitverzerrte Kräuter und Erze auf den Verheerten Inseln und bringt sie her, damit wir sie analysieren können.", sourceObjective = "Sammelt zeitverzerrte Kräuter und Erze.", progress = "Wie läuft es mit der Forschung?", completion = "Moratari wird begeistert sein, so viele Proben zu bekommen. Danke für Eure Sorgfalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90111] = { id = 90111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Dämonologie", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Dämonologie, also konzentriert Euch darauf, dämonische Gegner zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 75 Dämonen.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90112] = { id = 90112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Elite", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Elitegegner, also konzentriert Euch darauf, solche zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 25 Elitegegner.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90113] = { id = 90113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Grundlagen der Selbstverbesserung", description = "Wenn Ihr Euch verbessert, können wir Eure Kraft mit der Eures Artefakts vergleichen. Nur dann werden wir in der Lage sein, festzustellen, ob das Artefakt oder die Person, die es führt, wichtiger ist.\n\nGeht und werdet stärker, konzentrierter, erfahrener. Kehrt anschließend zu mir zurück, damit wir Eure Fortschritte festhalten können.\n\nDer Weg zur Selbstverbesserung ist lang, also übernehmt Euch nicht.", sourceObjective = "Schließt verschiedene Aktivitäten auf den Verheerten Inseln ab.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90114] = { id = 90114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Selbstverbesserung für Fortgeschrittene", description = "Wenn Ihr Euch verbessert, können wir Eure Kraft mit der Eures Artefakts vergleichen. Nur dann werden wir in der Lage sein, festzustellen, ob das Artefakt oder die Person, die es führt, wichtiger ist.\n\nGeht und werdet stärker, konzentrierter, erfahrener. Kehrt anschließend zu mir zurück, damit wir Eure Fortschritte festhalten können.\n\nDer Weg zur Selbstverbesserung ist lang, also übernehmt Euch nicht.", sourceObjective = "Schließt verschiedene Aktivitäten auf der Weltstufe Heroisch ab.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90115] = { id = 90115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Hainläufer", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Eure Einstimmung auf den Wald, also konzentriert Euch darauf, Gegner mit der Macht der Natur zu bekämpfen.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 100 Gegner, während 'Ruf des Waldes' Eure aktive Artefaktfähigkeit ist.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90119] = { id = 90119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "test" }
quests[90122] = { id = 90122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet Xy'vox den Verrenkten aus", description = "<Verwendet den Xy'vox' Zufluchtdämpfer, um Xy'vox den Verrenkten zu offenbaren und auszuschalten.>", progress = "Schaltet Xy'vox den Verrenkten aus.", completion = "Herausragende Arbeit. Für das Ausschalten des Ziels dieses Haftbefehls gibt es eine Belohnung." }
