quests[90127] = { id = 90127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet Arkanahetzer So'zer aus", description = "<Verwendet den arkanen Köder, um Arkanahetzer So'zer zu offenbaren und auszuschalten.>", progress = "Schaltet Arkanahetzer So'zer aus.", completion = "Herausragende Arbeit. Für das Ausschalten des Ziels dieses Haftbefehls gibt es eine Belohnung." }
quests[90517] = { id = 90517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Teil der Abmachung", description = "Die Bedrohung der Biokuppel: Primus durch die Schattenwache ist vorbei. Mein Reshiiband wird nicht mehr benötigt, um diese Anlage zu schützen. Nehmt es. Verwendet es mit Bedacht. Schützt unsere größte Investition überhaupt... unsere Existenz.\n\nBleibt fokussiert! Die Vorbotin hat bereits ein Mitglied Eurer Gruppe vertrieben. Sobald Ihr genug Reshiibänder habt, müsst Ihr nach wie vor gegen Dimensius antreten. Findet neben Artefakten auch Verbündete, die an unserer Seite stehen.", sourceObjective = "Nehmt Ve'naris Reshiiband.", progress = "Die Reshiibänder dienen dazu, Euch und Eure Verbündeten in die Nähe von Dimensius zu bringen. Ihr werdet mindestens zwei weitere benötigen, wenn dieser Plan aufgehen soll.", completion = "Ihr habt mein Band. Los... findet die restlichen. Lasst den Raumgänger die anderen Mitglieder des Geflechts kontaktieren. Fragt die Vorbotin, ob sie von irgendwelchen antiken Schrecken weiß, die eines in ihrem Besitz haben. Vergesst Regel Zwölf nicht... Beziehungen sind das A und O.", sourceObjectiveStatus = "unverified-source-field" }
quests[90545] = { id = 90545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Haken an der Sache", description = "Ein wesentlicher Bestandteil des Ökosystems der Oase ist das Unterwasserleben in unserem kleinen See.\n\nAllem Anschein nach befinden sich künstliche Organismen, die sogenannten Hydrobisse, im See. Ursprünglich wurden sie eingeführt, um Giftstoffe aus dem Wasser zu filtern, aber ihre weitere Anwesenheit bedroht das Gleichgewicht des Wassers.\n\nBitte entfernt diese mechanischen Fische sofort!", sourceObjective = "Fangt 7 Hydrobisse in der Oase.", progress = "Habt Ihr die Fische gefangen?", completion = "Gute Arbeit. Ich bin froh, dass ich mich nicht selbst um diese fiesen Fische kümmern musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[90557] = { id = 90557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wessen Schlüssel ist das?", sourceObjective = "Hey, wir haben einen merkwürdigen Schlüssel gefunden. Keine Ahnung, wem der gehört, aber fürs Hotel Inkontinental ist er nicht. Wollt Ihr ihn?", sourceObjectiveStatus = "unverified-source-field" }
quests[90630] = { id = 90630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Bündel voller Kristalle", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
