quests[90638] = { id = 90638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel voller Kristalle", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90659] = { id = 90659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leihgabe", description = "Nachdem Ihr nun Eure ewige Bronze habt, müssen wir nur noch das richtige Artefakt für Euch auswählen, die Bronze zu einem passenden Simulakrum der Waffe formen und dann durch einen Temporalknoten greifen und die beiden vertauschen.\n\nNiemand wird es merken.\n\nWir müssen nur daran denken, das Simulakrum zurück in diese Zeitlinie zu holen, dann geht alles gut.\n\nLasst uns als Erstes Eure Spezialisierung wählen. Die wird bestimmen, welches Artefakt wir uns borgen.", sourceObjective = "Wählt Eure Artefaktwaffe.", progress = "Artefakte benötigen starke Helden, um sie zu führen.", completion = "Faszinierend. Das Potenzial des Artefakts wurde vertieft, vielleicht dadurch, dass diese Zeitlinie zerfasert. Es kann mehr Macht bündeln als jede andere Version davon, die ich je gesehen habe.\n\nLasst mich diesen Datenpunkt gleich für Moratari aufzeichnen.\n\nAch, eine wichtige Erinnerung noch: Vergesst nicht, das bronzene Simulakrum später zurückzuholen, oder es passieren womöglich... merkwürdige Dinge.\n\nUnd sagt vielleicht nicht weiter, wie Ihr das erhalten habt. Das könnte das Experiment beeinträchtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90660] = { id = 90660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein goldener Umstand", sourceObjective = "Ich wünsche Euch viel Erfolg auf Euren Abenteuern, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[90661] = { id = 90661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchtriebene Duos" }
quests[90663] = { id = 90663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Besitz stehlen", description = "Ve'nari hat viele Gefallen eingefordert, um die Wiederherstellung der Oase in Gang zu bringen. Viele Händler aus Tazavesh haben für diesen guten Zweck gespendet, doch andere sahen ihn eher als eine Möglichkeit, sich selbst zu bereichern.\n\nEin nicht besonders vertrauenswürdiger Importeur hat eine große Ladung statisch versiegelter Gegenstände von den Docks gestohlen. Ich könnte jemanden mit Euren Fähigkeiten brauchen, um die Ladung zurückzuholen.", sourceObjective = "Sprecht mit Xy'dax und bringt die vermissten Importe zurück.", progress = "Habt Ihr meine vermissten Gegenstände wiederbeschafft?", completion = "Mit so viel hätte ich nicht gerechnet! Vielleicht sind das nicht nur meine Importe? \n\nAber es ist trotzdem gut, dass ich diese Sachen wiederhabe. Ich habe hier etwas, um Euch für Eure Mühe zu entlohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90665] = { id = 90665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschnitzte Wappen", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90666] = { id = 90666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel voller Kristalle", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90667] = { id = 90667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzaubertes runenverziertes Astralwappen", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90701] = { id = 90701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feige Jubelbomben", description = "Goblins lieben Bomben, das verstehe ich. Aber muss wirklich ALLES in die Luft fliegen?\n\nTut mir bitte einen Gefallen: Sucht in Eurer nächsten Runde Durchtriebene Duos eine Jubelbombe in einer der Requisiten, die wie Holzbäume und Pflanzkübel aussehen.\n\nWenn Ihr die Bombe gefunden habt, haut Ihr einmal ordentlich drauf. Aber bevor sie \"hochgeht\"! Keine Sorge, sie sind Feiglinge.", sourceObjective = "Findet eine Jubelbombe, die in einer durchtriebenen Requisite versteckt ist. Haut drauf, bevor sie hochgeht.", progress = "Diese Jubelbomben betteln förmlich darum, {name}. Sucht eine in einer Runde Durchtriebene Duos und haut drauf.", completion = "So wird's gemacht, BESKYR. Man muss diesen Bomben zeigen, wer der Boss ist, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[90705] = { id = 90705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche", description = "Interessiert Ihr Euch für die Geschichte Eurer Welt? Würdet Ihr gern mehr erfahren?\n\nLehrensucher Cho ist herumgereist, um Geschichten von wichtigen historischen Ereignissen und Figuren aus Azeroth und darüber hinaus zusammenzutragen. Besucht ihn doch mal in Eurer Hauptstadt. Er teilt sicher gern eine Erzählung aus der Vergangenheit mit Euch.\n\nOder sogar mehr als eine! Er plaudert wirklich gern.\n\nSagt ihm, dass Assistentin Lali Euch schickt.", sourceObjective = "Sucht Lehrensucher Cho in Dornogal, Sturmwind oder Orgrimmar auf.", completion = "Wie? Lali schickt jetzt schon Besucher zu mir?\n\n<Lehrensucher Cho lacht lauthals.>\n\nNa, wer auch sonst?\n\nAber sie hat recht. Das einzige, was mir noch mehr Freude macht, als Geschichten zusammenzutragen, ist, sie weiterzuerzählen! Setzt Euch, ich teile eine Erzählung mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[90719] = { id = 90719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borgende Verderbnis", description = "<Abenteurer/Abenteurerin>, ich habe eine unglaubliche Entdeckung gemacht.\n\nBei der Analyse der Erinnerungen aus der Vergangenheit bin ich zu der Erkenntnis gekommen, dass ich die Verderbniseffekte, die damals eingesetzt wurden, neu erschaffen könnte, obgleich auch auf viel geregeltere Weise.\n\nIch bitte Euch daher, einige Schwarzblutrückstände für mich zu sammeln. Besiegt dafür die Bosse der verderbten oder verlorenen Bereiche auf der Karte. Außerdem benötige ich auch noch ein paar der versetzten verderbten Andenken.", sourceObjective = "Sucht in den verstörenden Visionen nach Schwarzblutrückständen und versetzten verderbten Andenken von den Bossen der verderbten und verlorenen Bereiche.", progress = "Wart Ihr erfolgreich?", completion = "Ja, durch das Verbinden dieser Rückstände mit den versetzten verderbten Andenken kann ich... Ja, genau so... Und dann mit ein wenig bronzener Magie... So. Geschafft.\n\nNun, da ich weiß, wie ich vorzugehen habe, kann ich noch mehr davon herstellen, wenn Ihr mir weitere versetzte verderbte Andenken bringt. Ich werde in der Zwischenzeit versuchen, den Vorgang noch weiter zu optimieren. Kommt später wieder vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[90729] = { id = 90729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beidseitiger Vorteil", description = "Nicht alles, was Ihr gestern geborgen habt, gehört mir, aber seien wir ehrlich - wir behalten es trotzdem!\n\nXy'daz zieht seit Jahren Leute über den Tisch. Jetzt ist er an der Reihe, Verluste einzustreichen!\n\nNun, das kann uns beiden zugute kommen. Wenn Ihr die Hälfte der übrig gebliebenen Waren für mich verkauft, könnt Ihr den Rest behalten!", sourceObjective = "Verkauft 6 Schattenhandel-Überbestand.", progress = "Habt Ihr die Gegenstände verkauft?", completion = "Sehr gut! Vielleicht sollte ich Euch häufiger für mich arbeiten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[90731] = { id = 90731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Verderbnis", description = "Willkommen zurück, <Abenteurer/Abenteurerin>. Ich habe eine weitere Entdeckung gemacht, aber dafür sind weitere Tests nötig. \n\nIch vermute, dass sich in den verlorenen Bereichen der verstörenden Visionen ein seltenes Schwarzblutkoagulat verbirgt. Es könnte der Schlüssel zur Verstärkung der Verderbniseffekte sein... Auf eine sichere Weise.\n\nWenn Ihr Euch Zugang zu diesen Bereichen verschaffen und dieses Objekt finden könnt und wenn Ihr mir noch weitere versetzte verderbte Andenken bringt, sollte ich die Wirksamkeit der Verderbniseffekte erhöhen können.", sourceObjective = "Sucht in den verstörenden Visionen nach Schwarzblutkoagulat und versetzten verderbten Andenken von den Bossen der verlorenen Bereiche.", progress = "Wart Ihr erfolgreich?", completion = "Nun, das sieht vielversprechend aus... Das Koagulat katalysiert langsamer und somit lässt sich die erhöhte Verderbnis besser eindämmen... Ja, so kann ich mehr verderbtes Material herstellen, aber ohne die negativen Nebeneffekte.\n\nBedauernswerterweise kann ich das Gemisch nicht lange stabilisieren. Die Effekte sind nicht von Dauer. Es tut mir leid, Abenteurer, aber wir sollten sie nutzen, solange wir die Gelegenheit dazu haben. \n\nBringt mir noch mehr versetzte verderbte Andenken, dann kann ich weitere große Verderbnismixturen für Euch herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90747] = { id = 90747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der falsche Blaucephalus", description = "Wir beide hatten einen etwas holprigen Start, aber es gibt etwas, das Ihr wissen solltet.\n\nDieser alte Schieferrücken, mit dem Ihr die Importe transportiert habt? Ich dachte, das wäre nur ein weiteres müdes Nutzvieh, aber wie sich herausgestellt hat, war er der wahre Schatz.\n\nEin seltener Blaucephalus, der ein Vermögen wert ist!\n\nIhr solltet besser herausfinden, wohin er verschwunden ist, und warum Ba'eth es nicht gerade eilig zu haben scheint, die Profite zu teilen!", sourceObjective = "Sprecht mit Ba'eth und anderen.", completion = "Gut. Das wird ein profitables Unterfangen... für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[90754] = { id = 90754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsreiten", description = "Dieses Land ist weitläufiger, als ich es in Erinnerung hatte. Aber eine Gelehrte, die etwas auf sich hält, ist stets vorbereitet.\n\nIhr werdet ein geflügeltes Reittier benötigen, sowie die Fähigkeit, geschwind darauf zu reiten, um ein größeres Gebiet abdecken zu können.\n\nIch erinnere mich, dass Lord Andestrasz uns in der Vergangenheit schon einmal damit geholfen hat, nahe der Zeitlosen Insel in Pandaria. Schicken wir Euch zu diesem Moment in der Zeit zurück, damit Ihr etwas von ihm lernen könnt.\n\nKommt in entfernten Landen nicht zu weit vom Weg ab. Wir brauchen Euch immer noch hier. Kehrt über das Portal zurück, wenn Ihr Eure Lektionen gelernt habt.", sourceObjective = "Nehmt Morataris Portal zu Lord Andestrasz.", completion = "Fangen wir an. Wir konzentrieren uns auf die Grundlagen.\n\nKeine Sorge, die gewagten Manöver kommen später.", sourceObjectiveStatus = "unverified-source-field" }
quests[90755] = { id = 90755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie im Fluge", description = "Das sollte fürs Erste reichen. Behaltet die Grundlagen im Kopf, dann werdet Ihr Euch mit der Zeit verbessern.\n\nApropos Zeit: Ihr solltet Euch lieber auf den Weg machen. Das Portal dort bringt Euch zurück zu Moratari.", sourceObjective = "Kehrt zu Moratari zurück.", completion = "Hervorragend. Das sollte unsere Forschung beschleunigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90769] = { id = 90769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Blauer", sourceObjective = "Erhaltet Eure Belohnung.", completion = "Mög'n die Geister Euch schütz'n, Mann. Und Euren neuen blauen Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[90770] = { id = 90770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gaunerei", description = "Ich hab gehört, Ihr wollt das blaue Nutzvieh hab'n? Was für ein Traumgeschäft für mich. Der Basar steckt voller Möglichkeiten. \n\nAber gibt noch viel mehr Möglichkeiten an Orten, wo Schätze verborg'n sind. \n\nWisst Ihr, wo Ihr such'n müsst?\n\nGeht an diesen besonderen Ort und findet die Schätze, dann gehört der Blaue Euch.", sourceObjective = "Betretet den ungebundenen Raum und besorgt die Gegenstände, die Gaunah benötigt.", progress = "Habt Ihr die Schätze gefunden?", completion = "Gute Arbeit, Mann. Gaunah wird heute lächeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[90773] = { id = 90773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch ist Geld", description = "Da ich Euch helfe, werdet Ihr sicher nichts dagegen haben, den Gefallen zu erwidern.\n\nIch habe einen ständigen Bedarf an frischem, unverschmutztem Fleisch, das schwer zu beschaffen ist. Die Oase kommt nicht in Frage, aber die Tiere, die in diesen Sanden leben?\n\nIch habe eine Liste von allem, was ich brauche. Bringt mir diese Sachen und ich sage Euch, was Ihr wissen müsst.", sourceObjective = "Sammelt 12 Staubrückenflanken, 5 Schlickflügelschweife und 5 Sturzflüglereier.", progress = "Habt Ihr das Fleisch besorgt?", completion = "Nun, wie versprochen.\n\nIch habe den blauen Schieferrücken an einen Fremden wie Euch verkauft. Aber das war kein großer Held, eher ein etwas unbeholfener Typ.\n\nKommt morgen wieder. Er kommt hier regelmäßig zum Essen vorbei. Und er riecht nicht nur am Essen, er isst es!", sourceObjectiveStatus = "unverified-source-field" }
quests[90776] = { id = 90776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antike Kuriositäten: Kampf", description = "<Als Ihr die Kuriosität in Händen haltet, seht Ihr, dass sie leuchtet. Das muss Bedeutung haben. Die Forscherliga wäre sicher interessiert.>", sourceObjective = "Setzt eine Kampfkuriosität ein und rüstet Brann Bronzebart damit aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[90778] = { id = 90778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antike Kuriositäten: Unterstützung", description = "<Als Ihr die Kuriosität in Händen haltet, seht Ihr, dass sie leuchtet. Das muss Bedeutung haben. Die Forscherliga wäre sicher interessiert.>", sourceObjective = "Setzt eine Unterstützungskuriosität ein und rüstet Brann Bronzebart damit aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[90779] = { id = 90779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rissiger Schlüsselstein", description = "Zerrissene Bilder heldenhafter Taten zucken wie Blitze durch Eure Gedanken, als Ihr den Stein berührt, doch genauso schnell verblassen sie auch wieder.\n\nMöglicherweise lässt sich die Magie des Steins mit einer angemessen beeindruckenden Heldentat ein für alle Mal stabilisieren?", sourceObjective = "Schließt einen beliebigen Dungeon auf Mythisch 2 oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[90781] = { id = 90781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Krieges: K'aresh", description = "Es gibt Gerüchte über einen aufkeimenden Konflikt in K'aresh. Geht und findet mehr darüber heraus!", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Krieges in K'aresh.", progress = "Geht und bringt zu Ende, was Ihr angefangen habt.", completion = "Eure schnelle Rückkehr überrascht mich, gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[90840] = { id = 90840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Die Dracheninseln sind ein gefährlicher und unerforschter Ort. Wir müssen Euch gut vorbereiten.\n\nIhr seid nun stark genug, um eine Kampfspezialisierung zu wählen.\n\nDamit schaltet Ihr eine Reihe neuer Fähigkeiten frei, um Euch den Gefahren dieses Ortes zu stellen.\n\nWählt jetzt Eure Kampfspezialisierung.", sourceObjective = "Wählt Eure Kampfspezialisierung.", sourceObjectiveStatus = "unverified-source-field" }
quests[90843] = { id = 90843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Dracheninseln", description = "Es ist an der Zeit, dass sich unsere Wege trennen. Ich muss mich weiter im Inneren der Dracheninseln an einem Ort namens Azurblaues Gebirge dringenderen Angelegenheiten widmen.\n\nNaleidea Flussglanz von der Drachenschuppenexpedition könnte Eure Hilfe gebrauchen.\n\nGute Reise, {name}. Ich freue mich auf unser nächstes Treffen!", sourceObjective = "Trefft Euch mit Naleidea Flussglanz, um Euer Abenteuer auf den Dracheninseln zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90869] = { id = 90869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Optik ist alles", description = "Also, die hohen Tiere in der Marketingabteilung finden, dass Ihr einen guten Partner braucht, der Euer... Ihr wisst schon, \"Ich bringe alle um mich herum für Gold um\"-Image etwas zu mildern.\n\nWir haben zwei von Fokusgruppen abgesegnete Goblins da drüben stehen, die für alles bereit sind. Ihr habt die freie Wahl. Sassy kümmert sich um den Papierkram.\n\nOh, schaut mich nicht so an. Ihr müsst der Öffentlichkeit lediglich Eure ewige Liebe demonstrieren. Was passiert, wenn die Kameras aus sind, kümmert niemanden mehr. Für Euren Ruf wird das Wunder wirken!", sourceObjective = "Sprecht mit Sassy Hartzang, um Euch einen \"Marketingpartner\" auszusuchen.", completion = "Na bitte! Schön künstlich, genau so sieht gutes Marketing aus.\n\nUnd ich bin gerade mit dem Papierkram für Eure andere große Rufaufbesserung fertig geworden. Ich glaube, das wird Euch gefallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[90870] = { id = 90870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mampf sammeln", description = "Ah, da seid Ihr ja! Das Braufest steht vor der Tür, aber wir haben ein kleines Problemchen. Ohne Mampf gibt's auch kein zünftiges Festmahl und so ein paar vermaledeite Hozen haben sich wohl gedacht, es wäre lustig, wenn sie uns unser Essen klauen. Die haben sicher einfach nur Hunger, aber das bringt unsere Pläne ganz schön durcheinander!\n\nVon Euch erwarte ich jetzt also Folgendes: Spürt mir diese Hozen auf und bringt mir die geklauten Nahrungsmittel zurück. Mit etwas Glück liegen sie einfach herrenlos irgendwo herum. Stellt bei Eurer Rückkehr einfach alles zu dem Wagen da hinten.", sourceObjective = "Sammelt Taschen mit Braufestzutaten und stellt sie am Wagen ab.", progress = "Ohne die Zutaten fällt das Fest ins Wasser!", completion = "Ah, Ihr habt es geschafft! Die Köche werden begeistert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[90879] = { id = 90879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braumeisterküche", description = "Nachdem Ihr uns die Zutaten gebracht habt, können wir uns endlich ans Kochen machen! Für die ganze Meute müssen wir ordentlich ranklotzen.\n\nUnsere Speisekarte ist kurz, aber lecker: Gerstensuppe, Brezeln und natürlich leckeres Bier!\n\nSeid Ihr soweit?", sourceObjective = "Befolgt die Schritte, um das Braufestessen und ein süffiges Gebräu zuzubereiten.", progress = "Aab an den Herd!", completion = "Ah, die Brezeln duften bis hierher. Ihr habt da was ganz Feines zubereitet. Das wird selbst die Zwerge mit dem feinsten Gaumen überzeugen!", sourceObjectiveStatus = "unverified-source-field" }
quests[90880] = { id = 90880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servieren mit Stil", description = "In der Küche habt Ihr Euch wacker geschlagen; jetzt geht's ans Bedienen! Beim Braufest geht's nicht nur ums Essen, sondern darum, dass sich alle wohlfühlen.\n\nIhr nehmt Bestellungen entgegen, bringt Essen an die Tische und schenkt den Gästen nach - und das immer mit einem Lächeln auf den Lippen.\n\nJetzt raus mit Euch und zeigt den anderen, wie man's richtig macht. Ohne gute Bedienungen läuft auf dem Braufest nichts!", sourceObjective = "Nehmt Kundenbestellungen auf und serviert das Essen.", progress = "Lächeln nicht vergessen!", completion = "Ich finde, Ihr habt Euch eine kleine Auszeit verdient, nach der ganzen harten Arbeit, die Ihr geleistet habt, aber kommt mir nicht auf falsche Gedanken! Rund ums Braufest gibt's noch immer jede Menge zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[90882] = { id = 90882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnollweg", sourceObjective = "Tötet 10 Gnolle in Hammerfall.", completion = "Hervorragende Arbeit. Uns bleibt jedoch keine Zeit für eine Pause.\n\nWir haben Nachricht von weiterem Chaos im Hochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[90883] = { id = 90883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Go'Sheks Hof", sourceObjective = "Reist zu Go'Sheks Hof", completion = "Ich hätte nie mit so viel Hilfe gerechnet! Bitte, Ihr müsst sie aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[90885] = { id = 90885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine hübschen Kürbisse", description = "Die Kobolde und Oger sind aus dem Nichts aufgetaucht und haben uns von unserem Hof verjagt!\n\nIch hielt es zuerst für eine Intrige der Allianz, bis ihr aufgetaucht seid. Vielleicht will uns die Allianz doch helfen.\n\nIhr müsst mir helfen, meine kostbaren Kürbisse zurückzuholen. Ich habe sie während der gesamten Ernte kultiviert!\n\nIhr geht voraus. Ich schnapp mir die Kürbisse, wenn Ihr sie findet.", sourceObjective = "Bergt 4 preisgekrönte Kürbisse.", completion = "Das sind... ziemlich viele Kürbisse.\n\nIch denke, unser Bauernfreund sollte sie zurück nach Hammerfall bringen. Verstärkungen der Horde sollten bereits dort sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[90886] = { id = 90886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Plan, von Kobold und Oger", description = "Die Kobolde und Oger hier scheinen eine Art Plan für ihren Angriff zu haben.\n\nIch nehme nicht an, dass diese Pläne besonders präzise geschrieben sind, also brauche ich wohl mehrere davon, um mehr über die Machenschaften der Oger herauszufinden.", sourceObjective = "Sammelt 7 schlecht geschriebene Pläne.", progress = "Habt Ihr die Pläne? Sie sollten bei den meisten der Gegner auf dem Hof zu finden sein.", completion = "Wie ich mir gedacht habe.\n\nIch kann das kaum entziffern.", sourceObjectiveStatus = "unverified-source-field" }
quests[90887] = { id = 90887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Bauern Nemesis", description = "Bauer Bruvk erwähnte einen Oger namens Runk, der die Gruppe hierhergeführt hat.\n\nDiese Kreaturen werden den Ort nicht verlassen, solange dieser Oger sie befehligt.", sourceObjective = "Tötet Runk.", progress = "Wir bleiben hier und schützen die verbleibenden Bauern, während Ihr Euch um Runk kümmert.", completion = "Das sollte helfen, die Kreaturen zu vertreiben. Ohne einen Anführer werden sie flüchten, wenn die Verstärkungen von Allianz und Horde erscheinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90888] = { id = 90888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung von Burg Stromgarde", description = "Die Pläne, die Ihr gefunden habt, deuten darauf hin, dass die Oger Nahrung für einen Großangriff auf Burg Stromgarde sammeln!\n\nOder dass sie mit den Vorräten eine Garde für einen Kerl namens Stromburg aufstellen wollen. Es war eine sehr freie Übersetzung.\n\nGehen wir mal davon aus, dass Ersteres gemeint ist: Auf geht's!", sourceObjective = "Reist nach Burg Stromgarde.", completion = "Das sieht schlimm aus, aber wir werden schon damit fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[90892] = { id = 90892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubere Luft: Höllischer Himmel", description = "<Der Himmel ist voll von verbleibender Zeitenergie und Dämonen, die aus anderen Zeitlinien einfallen.\n\nIch sollte Eternus helfen, indem ich da oben aufräume. Die zusätzliche Bronzeenergie wäre auch nicht zu verachten.>", sourceObjective = "Sammelt Bronze, indem Ihr durch 10 Dämonen der verlorenen Legion und 25 Bronzepartikel fliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90893] = { id = 90893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwehr der Belagerung", description = "Wir müssen die Belagerung von Stromgarde um jeden Preis beenden.\n\nStürzt Euch in die Schlacht und schwächt die Truppen der Oger.\n\nStromgarde sollte sich wieder sammeln können, wenn sie die Oberhand gewinnen.", sourceObjective = "Wehrt die Belagerung der Oger vor Burg Stromgarde ab.", completion = "Die Belagerung ist vorbei. Wir haben ihren Anführer umstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90896] = { id = 90896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Oger", description = "Der Anführer der Belagerung versteckt sich noch immer in dem ehemaligen Lager der Horde.\n\nEr hat es geschafft, sich hinter mehreren seiner Kohorten vor Jainas Zauber zu verbergen.\n\nIch überlasse Euch die Ehre, ihn zu stellen. Jaina und ich werden hierbleiben und dafür sorgen, dass keine Überbleibsel der Belagerungstruppen zurückkehren.\n\nMacht dem ein Ende.", sourceObjective = "Tötet Ro'grok", progress = "Besiegt Ro'grok und beendet die Belagerung.", completion = "Die Belagerung ist vorüber. Das Arathihochland wird nun hoffentlich wieder einigermaßen zur Ruhe kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90897] = { id = 90897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Stromgarde", description = "Ich denke, wir können uns glücklich schätzen, dass es bis auf eine Gruppe zu ehrgeiziger Oger keine größere Bedrohung gab.\n\nDas gilt jedoch nicht für andere Gefahren, die in Azeroth lauern.\n\nKommt. Kehren wir nach Stromgarde zurück, um weitere Angelegenheiten zu besprechen.", sourceObjective = "Trefft Euch mit Jaina Prachtmeer in Burg Stromgarde.", completion = "Es ist schön zu sehen, wie ausgelassen die Einwohner sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[90898] = { id = 90898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Hammerfall", description = "Wir haben nicht immer so viel Glück, dass ein Plan wie dieser so schnell und ohne das ein oder andere Überraschungsportal vereitelt wird.\n\nTrotzdem lauern in Azeroth noch weitere Gefahren. Ich weiß, dass Ihr bei einigen helfen könnt.\n\nKehren wir nach Hammerfall zurück und sehen, wie gut sie sich erholen.", sourceObjective = "Kehrt nach Hammerfall zurück.", completion = "Hammerfall wird sich schnell erholen und stärker als zuvor aus dieser Belagerung hervorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90901] = { id = 90901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifakten schaffen", description = "Artefakte sind mächtiger, als es den Anschein hat, {name}.\n\nAllein die Verwendung eines Artefakts lässt seine Legende wachsen, und seine Macht wird es im selben Maße tun.\n\nWenn Ihr jedoch das volle Potenzial dieser Macht ausschöpfen wollt, müsst Ihr ewige Macht in die Boni des Artefakts fokussieren. Je mehr Boni ermächtigt werden, desto eher wird das wahre Potenzial des Artefakts erschlossen, und seine Legende wird sich allen offenbaren.\n\nFangen wir an.", sourceObjective = "Schaltet Artefaktboni mit ewiger Macht frei, die Ihr durch das Erbeuten von Epochenandenken von beliebigen Gegnern erhalten könnt.", progress = "Ihr müsst das volle Potenzial Eures Artefakts erschließen, um seine Auswirkungen auf diese Zeitlinie zu verstehen.", completion = "Vergesst nicht, die ewige Macht, die Ihr sammelt, auf Euer Artefakt zu fokussieren.\n\nJe mehr Macht Ihr ihm gewährt, desto schneller sammelt Ihr mehr ewige Macht und stärkt so die Legende Eures Artefakts, wie auch Eure eigene.", sourceObjectiveStatus = "unverified-source-field" }
quests[90911] = { id = 90911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer nächstes Abenteuer", sourceObjective = "Wählt Euer nächstes Abenteuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[90938] = { id = 90938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sprung durch die Leere", description = "Fleischling, was wisst Ihr über den ungebundenen Raum? Ihr kennt doch bestimmt jemanden, der dort war.\n\nFrüher dachten wir, dass nur Energiewesen wie die auf K'aresh phasentauchen könnten. Doch seit der Rückkehr der Vorbotin, hat sie ein Mittel geschaffen, mit dem auch feste Kreaturen mithilfe von Reshiiwickeln zu Energie werden können.\n\nMein Name ist Hashim und ich bin im Besitz einiger Reshiiwickel. Wir suchen verzweifelt nach Abenteurern, die mächtig genug sind, sich in die lukrativen Tiefen des ungebundenen Raums zu begeben.", sourceObjective = "Trefft Hashim an der Zo'Shuulwarte.", completion = "Ich kann Euch alles zur Verfügung stellen, was Ihr braucht, um den ungebundenen Raum zu erkunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[90968] = { id = 90968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanisches Rumoren", description = "In Khaz Algar hört man überall Gerüchte von titanischen Kräften, die angeblich gesichtet wurden. Brann bat Dagran Thaurissan II um Unterstützung, um zu untersuchen, ob etwas Wahres dran ist.", sourceObjective = "Sucht Dagran Thaurissan II im Tiefenforscherhauptquartier in Dornogal auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[90969] = { id = 90969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanenkonsolen", description = "<Abenteurer/Abenteurerin>, die Gerüchte sind wahr. Ich habe die Truppen der Titanen selbst gesehen und sie sind nicht freundlich. Wir müssen versuchen herauszufinden, warum sie jetzt auftauchen, und sie dann daran hindern, allzu viel Schaden anzurichten.\n\nStellt diese abtrünnigen Konstrukte und haltet sie auf. Um Euch zu helfen, habe ich einige Titanenkonsolen beschafft. Ich konnte sie in den betroffenen Gebieten aufstellen. Darüber kann ich mit Euch kommunizieren, wenn Ihr draußen unterwegs seid. Ich denke, wir können sie auch gegen diese Titanentruppen einsetzen.", sourceObjective = "Findet eine von Dagrans Titanenkonsolen in einer überladenen Tiefe.", completion = "{name}, diese Konsolen sind von der Anwesenheit der Titanen überladen. Wenn wir sie besiegen und Titanenscheiben bergen können, kann ich die Konsole vermutlich ermächtigen, sodass sie Euch in ihrem Bereich Verstärkungen verleihen, die Euch dabei helfen, diese Titanenkonstrukte zurückzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90970] = { id = 90970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Titanenscheibenfrage", description = "Wir müssen mehr Titanenscheiben bergen. Dringt tiefer in das Gebiet vor, sucht die Titanenkonstrukte und besiegt sie. Sie sollten Scheibenscherben bei sich tragen. Diese Konsole kann sie zusammensetzen und auf ihre Daten zugreifen.\n\nVergesst nicht, außerdem nach Schatzkammern zu suchen. Die Konstrukte scheinen den Bewohnern zu helfen, vielleicht haben einige von ihnen weitere Titanenscheiben mit anderen Schätzen eingelagert.", sourceObjective = "Bergt Titanenscheibenscherben und entledigt Euch der Titanenkonstrukte in der Tiefe.", progress = "Abenteurer? Seid Ihr das?", completion = "Habt Ihr die Fragmente gefunden? Während Ihr fort wart, ist mir eingefallen, dass ich ja auch einige bei meinem Besuch an diesem Ort gefunden habe. Ich habe sie in einem Beutel neben der Konsole versteckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[90971] = { id = 90971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überladene Konsole", description = "Mit den Scherben, die Ihr gefunden habt, können wir die Konsole nutzen, um die Titanenscheiben wiederherzustellen und auf mächtige Verstärkungen zuzugreifen.\n\nNutzt die Reparaturfunktion der Konsole, um eine Titanenscheibe herzustellen. Nutzt diese Scheibe dann, um einen Startknoten auf der Nutzeroberfläche der überladenen Konsole auszuwählen.", sourceObjective = "Stellt eine Titanenscheibe wieder her und gebt sie aus, um einen der Startknoten im Technikbaum der Überladungskonsole freizuschalten.", progress = "Hat es geklappt?", completion = "Meine Konsole zeigt eine Veränderung an. Die überladene Konsole leitet überschüssige Energie zu einem neuen Knoten. Das sollte Euch die Verstärkung dieses Knotens verleihen, wenn Ihr in andere Bereiche vordringt, in denen Titanenkonstrukte erwacht sind.\n\nWir werden die Energie der Titanen gegen ihre eigenen Truppen einsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[90972] = { id = 90972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gemeinsame Sache", description = "{name}! Ich habe gehört, dass Ihr auf K'aresh seid. Gut. Ich brauche Hilfe.\n\nMein Lehrling Leona forscht an neuen Möglichkeiten zur Nutzung der Macht der Leere. Sie hat sich an einen Dämonenjäger namens Adarus gewandt, um herauszufinden, ob die Methoden der Illidari sie vielleicht weiterbringen können.\n\nUm ehrlich zu sein, traue ich diesem Adarus nicht. Er ist kein... Gelehrter. Im Gegensatz zu Leona.\n\nLeona wollte ihn nur bei seinen Versuchen, die Leere zu kontrollieren, beobachten, aber jetzt ist sie verschwunden. Bitte spürt sie auf. Sprecht mit Adarus. Er weiß irgendwas.", sourceObjective = "Sprecht mit Adarus.", completion = "Adarus schickt Euch? \n\nSein mangelndes Vertrauen in meine Fähigkeiten und seine Unfähigkeit, Aufgaben zu delegieren, sprechen Bände.", sourceObjectiveStatus = "unverified-source-field" }
quests[90995] = { id = 90995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft der Teufelshammer", description = "Ach, Moment! Natürlich fällt mir das Wichtigste just in dem Moment ein, in dem ich Euch losschicke!\n\nDie Version von Euch aus dieser Zeitlinie hat eine bedeutende Entscheidung für die Zukunft aller Dämonenjäger getroffen. Die Wahl Eures persönlichen Champions erschuf zwei abweichende Zeitlinien für das Schicksal der Illidari.\n\nIhr werdet Euch entscheiden müssen, welche dieser divergierenden Zeitlinien Ihr erkunden möchtet. Was fühlt sich für Euch richtig an?", sourceObjective = "Wählt Euren persönlichen Champion.", completion = "Nun gut, wir werden diese Version der Zeitlinie untersuchen. Lasst uns sehen, was die Zukunft... äh, Vergangenheit der Illidari bereithält.", sourceObjectiveStatus = "unverified-source-field" }
quests[91009] = { id = 91009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dateninformationssicherungsbehältnis", description = "<Abenteurer/Abenteurerin>, könnt Ihr mich hören? Ich habe ein kleineres Gerät der Titanen entdeckt, das Dateninformationssicherungsbehältnis, das Ihr an Eurem Gürtel tragen könnt. Es sollte kleinere Titanenscheiben lesen können und Euch Kräfte verleihen, die Ihr überall nutzen könnt.\n\nAber jedes dieser Geräte braucht ein wenig Starthilfe. Wenn Ihr genug Staub in diesen Tiefen aufwirbelt, sollte das einen Funken erzeugen, der Euer Gerät lebenslang mit genug Energie versorgen sollte.", sourceObjective = "Schließt eine Tiefe ab um das Gerät aufzuladen.", completion = "Schließt das Gerät an. Ja! Das Gerät ist aufgeladen.\n\nGut, ich sollte die Initiierungssequenz starten können... und es läuft. Es sind schon zwei Scheiben eingespeist. Und das Menü listet Bereiche für Euch auf, in denen andere Miniatur-Titanenscheiben zu finden sind. Ich glaube, ich kann das Gerät verbessern, aber ich brauche Zeit. Sucht mich später wieder auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[91026] = { id = 91026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verbesserung einsammeln", description = "Hallo? Hallo! Ihr seid zurück! Perfekt!\n\nIch habe die Titanenkonsole untersucht und einige neue Informationen zu den überladenen Bereichen und den fehlerhaften Direktiven gesammelt, die gefunden wurden. Das könnte der Schlüssel zu ihrem unerwarteten Verhalten sein, aber ich brauche mehr Zeit, um sicherzugehen.\n\nKehrt in die Tiefen zurück, dann können wir die Ergebnisse dieser fehlerhaften Direktiven prüfen. Die Informationen kann ich nutzen, um eine Verbesserung für Euren Gürtel zu bauen!", sourceObjective = "Schließt eine beliebige Tiefe ab.", progress = "Habt Ihr die Gegenstände?", completion = "Hier, ja... Mit diesen Informationen kann ich einige letzte Anpassungen vornehmen. Und mit dieser Direktive...\n\nGut, das sollte funktionieren. Wenn Ihr das in Euer Dateninformationssicherungsbehältnis einsetzt, sollte es die Effektivität der, hm... Effekte des Geräts verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[91030] = { id = 91030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Titanendirektiven", description = "Für meine Berechnungen brauche ich viel mehr Daten. Ich bin fast fertig mit einer weiteren Aufwertungskarte, aber ich bin nicht sicher, ob sie vernünftig integriert werden kann.\n\nWenn Ihr allerdings in die Tiefe zurückkehren und mehr Gegner besiegen könntet, kann ich beobachten, wie sie reagieren. Basierend auf ihren Reaktionen kann ich den Feinschliff an dieser Aufwertung für Euren Gürtel abschließen.", sourceObjective = "Schließt eine beliebige Tiefe ab.", completion = "Hmm, wie ich es mir dachte. Ja, ich muss das hier anpassen... fertig.\n\nDie gute Nachricht ist: Diese Aufwertung wird Euren Gürtel nicht explodieren lassen! Ich dachte, es bestünde eine geringe Möglichkeit, aber nicht mehr. Dank Euren Daten weiß ich, dass ich die Energiezufuhr zu hoch eingestellt hatte. Zum Glück habe ich Euch noch einmal losgeschickt, stimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[91031] = { id = 91031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grenzen ausreizen", description = "Nachdem Ihr letzte Woche gegangen seid, ist mir klar geworden, dass ich Euch mit dem Explosionspotenzial der Aufwertung Eures Gürtels vielleicht erschreckt habe. Das tut mir leid. Manchmal lasse ich mich etwas mitreißen.\n\nIch glaube jedoch, ich kann noch mehr aus diesem Gürtel rausholen. Zumindest ein wenig. Vollkommen ungefährlich versteht sich! Aus Euren Daten geht hervor, dass Ihr vielen Gegnern begegnet seid und viele Tiefen besucht habt. Das ist der Schlüssel. Kehrt für die letzte Aufwertung für Euren Gürtel noch einmal dorthin zurück.", sourceObjective = "Schließt eine beliebige Tiefe ab.", completion = "Die Daten Eures letzten Ausflugs sind genau das, was ich für eine neue Aufwertung brauche, aber dies ist die letzte Aufwertung für den Gürtel, wenn wir keine Kernschmelze provozieren wollen. Natürlich würde uns eine Kernschmelze jede Menge über die Beschaffenheit des Gürtels sagen...\n\nMama hat immer gesagt: \"Dagran! Wenn du schon uralte, unersetzbare Artefakte zerstören musst, zerstör gefälligst deine eigenen.\" Das ist also die letzte Aufwertung.\n\nHier ist die letzte Aufwertungskarte. Danke für Eure Hilfe. Ich hoffe, wir bekommen in der Zukunft noch weitere Gelegenheiten für Experimente!", sourceObjectiveStatus = "unverified-source-field" }
quests[91033] = { id = 91033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktüberwachung", description = "Willkommen zurück, <Abenteurer/Abenteurerin>. Ich möchte Euch darum bitten, diese Titanenkonstrukte weiter zu beobachten.\n\nWir haben sie an verschiedenen Orten in Azeroth gesehen, ich konnte aber noch nicht herausfinden, was ihr Ziel oder ihre Anweisungen sind. Vielleicht offenbart sich uns eine Erkenntnis, wenn Ihr mehr Informationen sammelt.", sourceObjective = "Schließt eine überladene Tiefe ab.", completion = "Ihr Verhalten hat sich nicht geändert. Wie frustrierend. Wenn Eure Daten zutreffen, scheinen sie sich zu beruhigen.\n\nWir werden abwarten müssen, ob diese Beobachtung sich bewahrheitet. Hier habt Ihr etwas Ausrüstung, die wir zusammengetragen haben. Ich hoffe, sie ist Euch bei dieser wissenschaftlichen Arbeit nützlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[91035] = { id = 91035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstrukt-Deeskalation", description = "Eure bisherigen Ergebnisse zeigen einen Rückgang in der Überladung der Konstrukte. Wir müssen abwarten, ob es eine Ausnahme ist, oder ob der Rückgang eskaliert...\n\nKehrt in diese überladenen Bereiche zurück, überprüft die Ladung der Konstrukte und berichtet mir davon.", sourceObjective = "Besiegt 5 Konstrukte und schließt eine überladene Tiefe ab.", completion = "Das ja ist ein gewaltiger Abfall. Wenn es so weitergeht, könnten diese Konstrukte schon demnächst verschwunden sein!\n\nWir wissen immer noch nicht, was sie geweckt hat! Was, wenn wir es nie herausfinden?! Ich hoffe, dass sie zurückkommen.\n\nOh nein! Ich will nicht, dass sie alles ruinieren. Ich hasse nur unbeantwortete Fragen.\n\nWenigstens werden wir besser vorbereitet sein, wenn sie wieder auftauchen. Danke für Eure Hilfe, {name}. Ich habe die Zahlen überprüft und Euer Gürtel sollte weiterhin funktionieren, auch wenn die Konstrukte sich zurückziehen.\n\nUnd hier habt Ihr eine letzte Vorratskiste als Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[91038] = { id = 91038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenjäger gesucht", description = "<Ein versengtes Schreiben wurde an die Wand genagelt.>\n\nDIE HÖLLE WIRD EUCH HOLEN!\n\nNun, da wir Eure Aufmerksamkeit haben, seid gewarnt, dass Schwefelsplitter in diese Welt eingetreten sind. Sie fühlen sich warm an und sollten unter keinen Umständen in den Kopf von Euch oder irgendwem anders gelangen oder in irgendein anderes lebenswichtiges Organ von Euch oder anderen gebohrt werden.\n\nBringt bitte alle Splitter, die Ihr findet, SOFORT zu uns nach Dornogal.\n\nUnd wenn Ihr kleine Dienerlinge seht, die Säcke voller Schätze tragen, TÖTET SIE AUF DER STELLE.", sourceObjective = "Bringt das Schreiben zu Baranar in Dornogal.", completion = "Wir sind dankbar, dass Ihr uns helfen wollt.\n\nSplitter unserer Zeitlinie sind in Eure Welt eingedrungen. Sie ist ein trostloserer und finsterer Ort als die Eure, wo manche Verbrecher zu Helden wurden und manche Helden nie eine Gelegenheit hatten.\n\nHelft uns, diese höllischen Fragmente der Zeit aufzuspüren und an ihren rechtmäßigen Platz zurückzubringen, dann werden wir Euch mit Rüstungen ausstatten, die in den Feuern unserer Welt gehärtet wurden.\n\nUnd solltet Ihr irgendwelche Schatzgoblins finden, die sich in Eurer Welt verstecken, ersuchen wir Euch, diese Monstrositäten zu erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91039] = { id = 91039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerins Bitte", description = "{name},\n\nGeya'rah und Danath haben Dornogal erreicht. Sie wirken betrübt über die wachsenden Spannungen im Arathihochland. Es klingt ernst. \n\nKönnt Ihr nach Dornogal kommen? Ich glaube, Eure Anwesenheit könnte in dieser Situation helfen.\n\nFaerin", sourceObjective = "Sprecht mit Faerin Lothar in Dornogal.", completion = "{name}! Danke, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[91042] = { id = 91042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[91044] = { id = 91044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger der Leere", description = "Ich tat alles, was ich konnte, um diesen Ausgang abzuwenden. Wenn Ihr ihn nicht durch das Portal geschubst hättet, dann hätte die ungebändigte Leerenenergie die Höhle um uns herum zum Einsturz gebracht.\n\nEr war stark. Ich glaube, in gewisser Weise war das sein Nachteil.\n\nTrefft mich in Shan'dorah. Ich muss Umbric Bericht erstatten und ihn darüber informieren, was hier passiert ist.", sourceObjective = "Trefft Euch erneut mit Magister Umbric und Leona in Shan'dorah.", progress = "Ich konnte das Brodeln der Leerenenergie bis hierhin spüren, {class}. Was genau ist passiert?", completion = "Ich hoffe inständig, dass Adarus wohlauf ist und dass er nicht uns die Schuld in die Schuhe schiebt. Die Ren'dorei haben schon genug Feinde.\n\nIch freue mich, dass Leona ein Durchbruch gelungen ist, auch wenn ihr das ohne Eure Hilfe nie gelungen wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[91052] = { id = 91052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Überladene Tiefen", description = "Etwas hat dazu geführt, dass feindselige Titanenkonstrukte aktiviert werden und in Höhlen und Bereiche um Khaz Algar eindringen. Reist an diese Orte und untersucht und eliminiert diese Bedrohung.", sourceObjective = "Schließt eine überladene Tiefe von The War Within auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Es ist beunruhigend nicht zu wissen, was diese feindseligen Titaneneinheiten an die Oberfläche gezwungen hat. Doch dank Eurer Bemühungen stellen sie keine Bedrohung mehr dar.", sourceObjectiveStatus = "unverified-source-field" }
quests[91061] = { id = 91061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Chaos", description = "Ihr findet es womöglich ironisch, aber uns läuft die Zeit davon, {name}. Mächtige Kräfte bedrohen die Zukunft von mehr als einer Welt.\n\nEs wird Nozdormu nicht gefallen, aber ich muss unsere Studien mit Experimenten beschleunigen. Ich habe eine fragmentierte Zeitlinie isoliert, die Ihr erkunden könnt. Aber seid gewarnt: Diese Welt entbehrt jeglicher Hoffnung. Nur so kann ich uns wirklich auf das vorbereiten, was bevorsteht.\n\nIch habe am Teufelsmonument hinter Euch eine Forschungskonsole eingerichtet. Nutzt sie, um diese verbotene Zukunft zu betreten, auf dass wir das Unergründliche in Erfahrung bringen können.", sourceObjective = "Erkundet die Weltstufe Heroisch.", completion = "Ihr seid mutiger, als ich dachte, {name}.\n\nBitte experimentiert weiter. Ich lasse nicht zu, dass wir eine gefährliche Zukunft unvorbereitet betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[91066] = { id = 91066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braumeisterküche", description = "Sehr gut, Ihr habt die Vorräte dabei. Jetzt kann das Schlemmen beginnen. Wir brauchen jede Menge Essen, um stark zu bleiben.\n\nDie Speisekarte ist klein, aber deftig: Gersteneintopf, auf dem Stein gebackene Brezeln und ein starkes Gesöff, damit der Horde nicht die Puste ausgeht!\n\nSeid Ihr soweit?", sourceObjective = "Befolgt die Schritte, um das Braufestessen und ein süffiges Gebräu zuzubereiten.", progress = "Facht ein Feuer an und macht Euch an die Arbeit!", completion = "Haha! Die Brezeln rieche ich bis hierher. Bei so einem Festmahl hätten sogar die mürrischen Zwerge nichts zu meckern!", sourceObjectiveStatus = "unverified-source-field" }
quests[91067] = { id = 91067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mampf sammeln", description = "Ah, da seid Ihr ja. Das Braufest steht vor der Tür, aber wir haben ein Problem. Ohne Futter gibt's kein ordentliches Festmahl und ein paar diebische Hozen dachten wohl, es wäre klug, uns unser Essen unter der Nase wegzuschnappen.\n\nUnd da kommt Ihr ins Spiel: Spürt mir diese Hozen auf und bringt zurück, was uns gehört. Ein paar Taschen liegen womöglich einfach auf dem Boden herum. Wenn Ihr alles beisammenhabt, stellt es an dem Wagen hinter mir ab.", sourceObjective = "Sammelt Taschen mit Braufestzutaten und stellt sie am Wagen ab.", progress = "Ohne die Zutaten fällt das Fest ins Wasser!", completion = "Ihr habt es geschafft! Die Köche werden begeistert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[91068] = { id = 91068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servieren mit Stil", description = "Ihr habt Eure Stärke in der Küche bewiesen, jetzt wird bedient! Beim Braufest dreht sich nicht alles nur ums Futtern, sondern darum, dass in jeder Ecke des Lagers Feierstimmung aufkommt.\n\nIhr werdet Bestellungen entgegennehmen, Teller schleppen und Bier ausschenken - wie ein echter Feierkrieger.\n\nUnd jetzt raus mit Euch - zeigt denen, wie man in der Horde richtig bedient! Mit leeren Krügen gerät das Braufest ins Stocken!", sourceObjective = "Nehmt Kundenbestellungen auf und serviert das Essen.", progress = "Lächeln nicht vergessen!", completion = "Ich finde, Ihr habt Euch eine Pause und ein starkes Gebräu nach all der harten Arbeit verdient, aber macht mir jetzt nicht schlapp! Das Braufest ist noch nicht vorbei und es gibt noch mehr als genug Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[91089] = { id = 91089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ky'veza besiegen", description = "Sie ist also hier, um ein Kopfgeld einzutreiben, was?\n\nHat ihr denn niemand klargemacht, dass es unhöflich ist, einen Champion Azeroths um die Ecke bringen zu wollen? Noch dazu einen Bronzebart?", sourceObjective = "Erhöht Eure Gegenstandsstufe, um Ky'veza in ihrer Tiefe der Stufe 8 auf K'aresh herauszufordern.", completion = "Puh! Und weg mit ihr.\n\nDieses ganze Herumgeschleiche in den Schatten und Hin- und Hergeteleportiere kann ich auf den Tod nicht ausstehen.\n\nNach der ganzen Aufregung wäre ein bisschen Urlaub vielleicht angebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[91093] = { id = 91093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als nur eine Phase", description = "Ungebundener Raum stellt eine fortlaufende Gefahr für unser Volk auf K'aresh dar. Es wimmelt dort nur so vor verbannten Seelen, kaputter Technologie und Monstern jeglicher Couleur.\n\nHelft dem Bund von K'aresh und besiegt unsere Feinde im ungebundenen Raum. Ihr könnt die Phasenleiter benutzen, um Euch beim Phasentauchen durch die Überreste von K'aresh zu bewegen.", sourceObjective = "Schließt Aktivitäten beim Phasentauchen im ungebundenen Raum auf K'aresh ab.", progress = "Ich träume von einem Tag, an dem wir K'areshi das Land frei und ohne Furcht durchstreifen können.", completion = "Eure Unterstützung kommt sehr gelegen, {race}. Der Bund hat eine weise Entscheidung getroffen, Euch darum zu bitten, uns bei unseren Bemühungen zu assistieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[91138] = { id = 91138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Schöpfer und Zerstörer", description = "Was für ein winziges Teilchen. Und bar jeder Macht, die T'uure einst nährte. Aber trotzdem ein unschätzbar wertvolles Relikt.\n\nWusstet Ihr, {class}, dass die Dunkelheit und das Licht für T'uure zwei untrennbare Aspekte einer größeren Wahrheit waren?\n\nWas die Kraft zur Schöpfung besitzt, kann ebenso zur Zerstörung eingesetzt werden. Demonstriert diese Lektion, dann werdet Ihr Euch selbst besser verstehen sowie den großen Naaru, dessen Opfer der Vernichtung eines gesamten Planeten Einhalt gebot.", sourceObjective = "Demonstriert Eure Meisterschaft über Leben und Tod.", completion = "Ah, ja. Ich spüre die Veränderung in Euch. Das Wachstum, das entsteht, wenn man mit der einen Hand Tod austeilt, und mit der anderen das Leben nährt.\n\nVielleicht wird Euch dieses kleine Andenken als Erinnerung an T'uure und seine Rolle in Dimensius' Schicksal dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91140] = { id = 91140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stück der Vergangenheit", description = "<Dieses kristalline Fragment hat sämtlichen Glanz verloren, der ihm einst innewohnte. Nun, da es endlich aus Dimensius' Schreckensgestalt befreit und in den Händen der Frommen ist, schimmert es kurz auf.\n\nVielleicht weiß jemand in Tazavesh mehr darüber.>", sourceObjective = "Zeigt das Fragment Om'en in Tazavesh.", progress = "Was ist das? Ah, ich verstehe. Es ist gut, dass Ihr zu mir gekommen seid.", completion = "Ein Fragment des verlorenen Naaru T'uure? Eingefangen in Dimensius' Gestalt?\n\nIch hätte nicht gedacht, dass ich so etwas einmal sehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[91142] = { id = 91142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wappenrock der Verbundenheit", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91143] = { id = 91143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschnitzte Wappen", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91173] = { id = 91173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme lodert ewig", description = "Diese Sureki sind recht hartnäckig! Dieser Hartnäckigkeit gilt es mit unseren Klingen zu begegnen.\n\nKönnen wir in den kommenden Kämpfen weiterhin auf Eure Unterstützung zählen?", sourceObjective = "Schließt das Szenario \"Nachtsturz\" ab.", progress = "Macht Euch kampfbereit, die Schlacht steht Euch noch bevor.", completion = "Ihr habt einen Augenblick des Friedens für uns herausgeschunden.\n\nRuht Euch aus, doch achtet stets darauf, dass Eure Klinge geschliffen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[91193] = { id = 91193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Deckstein 1 - Freischalten" }
quests[91203] = { id = 91203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Deckstein 2 - Freischalten" }
quests[91205] = { id = 91205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turboschub Ultrapremium-Luxus: Ungeheure Herausforderungen", description = "<Lorenhall hat ein Problem. Wir brauchen Folgendes. Eine erprobte Truppe, oder meinetwegen einfach eine zusammengewürfelte Gruppe von Haudraufs, die bereit is', unseren Kumpels in Lorenhall zur Seite zu stehen. Helft mit, den größten Teil unserer Konkurrenten aus dem Weg zu räumen, und wir entlohnen Euch großzügig.\n\nSchließt die Aufgabe ab und holt Euch eine besondere Belohnung von Beraterin Wrexxel vor der Schatzkammer von Dornogal ab. Angebot für kurze Zeit. Einige Einschränkungen gelten.>", sourceObjective = "Bezwingt vier beliebige Bosse in der Befreiung von Lorenhall auf dem Schwierigkeitsgrad \"Schlachtzugsbrowser\" oder höher oder schließt vier beliebige mythische Dungeons ab.", completion = "Danke vielmals. In Lorenhall geht's grad drunter und drüber. Wir sind für jede Hilfe dankbar.\n\nAlso, abgemacht is' abgemacht. Hier is', was wir Euch schulden.\n\nWir nennen das die Jackpotbelohnung für das erste Mal Helfen. Kommt wieder vorbei, wenn Ihr mehr Arbeit wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[91314] = { id = 91314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebundenes Potenzial", description = "{class}, mir wurde zugetragen, Ihr hättet den ungebundenen Raum erkundet? Dieser Ort ist von makelloser Leerenenergie durchsetzt. Ich würde ihn ja gerne selbst erkunden, doch die letzten, die ihn betreten haben, wurden von der Leere verzehrt.\n\nIch brauche Hilfe bei meiner Forschung. In der Leerennarbenhöhle gibt es phasenverlorene Kreaturen, die ich gebrauchen könnte, um ihre Essenz zu untersuchen. Ich wäre Euch dankbar, wenn Ihr mir diese Essenz bringen könntet.\n\nDoch seid vorsichtig.", sourceObjective = "Sammelt 5 phasenveränderte Essenz im ungebundenen Raum.", progress = "Konntet Ihr die phasenveränderten Essenzen sammeln?", completion = "Das wird meine Forschung zum ungebundenen Raum weiter voranbringen. Ich danke Euch.\n\nIch kann mir kaum vorstellen, welche Erkenntnisse über K'aresh wir nun gewinnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[91413] = { id = 91413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Zwielichtschwurs", description = "<Die alten Runen auf der Seite scheinen sich unter Eurem Blick zu winden. Ihre Macht scheint schnell zu schwinden.>\n\n<Ve'nari wäre sicher daran interessiert.>", sourceObjective = "Bringt das Mal des Zwielichtschwurs zu Ve'nari in der Oase von K'aresh.\n\nBereitgestellter Gegenstand:", completion = "Salhadaar hat dem Tod getrotzt, um Dimensius wiederzubeleben, und es wieder getan, als er Eurer Rache entkam.\n\n<Ve'nari hält einen Moment inne.>\n\nSchade, dass er entkommen ist, doch der alles Verschlingende ist vernichtet. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[91420] = { id = 91420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischtausch", description = "<Das geheimnisvolle Mineral pulsiert in Eurer Hand. Jemand in Tazavesh wird einen Nutzen dafür haben. Sucht auf dem Verhüllten Markt nach einem Interessenten.>", sourceObjective = "Bringt Eure Entdeckung zu Om'myuz in Tazavesh.\n\nBereitgestellter Gegenstand:", completion = "<Om'myuz sieht sich das Erz näher an.>\n\nDas ist ein ziemlich interessanter Stein, den Ihr gefunden habt. Ich würde ihn gerne genauer untersuchen, ebenso wie alle weiteren Steine, die Ihr findet. Was sagt Ihr zu einem Handel?\n\nAndere Mitglieder des Kartells Om auf dem Verhüllten Markt könnten ebenfalls mit Euch handeln wollen, wenn Ihr welchen begegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[91437] = { id = 91437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilnahmeaufruf", description = "<Ihr findet eine Schriftrolle in Eurer Tasche, die dort vorher nicht war.>\n\nHallo, hier ist Nostwin! Seid Ihr gerade beschäftigt? Nein? Dann helft uns doch, ZEITWISSENSCHAFT zu betreiben!\n\nEternus kann Euch mehr erzählen.\n\nSchön, danke Euch, tschüs!", sourceObjective = "Sprecht mit Eternus auf dem Ewigen Basar in der Nähe von Dalaran.", completion = "Ihr kommt genau recht, {name}. Nun kann die Forschung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91438] = { id = 91438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Heroische Taten in der Welt", description = "Überall auf den Verheerten Inseln gibt es Bedürftige. Sie suchen nach Hoffnung und tun sich schwer, welche zu finden. Ihr könnt diese Hoffnung verkörpern.\n\nSucht jene, die auf den Verheerten Inseln in Gefahr sind, und seid der Champion, den sie so dringend benötigen.\n\nSolche Taten formen Legenden.", sourceObjective = "Schließt 3 Weltquests auf der Weltstufe Heroisch ab.", completion = "Ein einziger heldenhafter Akt kann das Blatt wenden. Ein hoffnungsvolles Flüstern kann die Verzweiflung abwenden. So erhalten Legenden ihre Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[91439] = { id = 91439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Invasionspunkte (Heroisch)", description = "Die Legion kämpft nicht auf konventionelle Art und Weise. Sie täuschen, manipulieren und untergraben ihre Gegner wann immer möglich.\n\nDie Legion kennt keine festen Fronten. Sie öffnen einen Riss an einem Schwachpunkt, dann schwärmen sie daraus hervor und verbreiten Tod und Zerstörung. Sie greifen an, wann es ihnen genehm ist.\n\nDoch diese Strategie ist nicht unfehlbar. Mächtige Champions, die schnell reagieren und mobil sind, können diese Invasionen im Keim ersticken. Haltet die Legionsinvasion auf. Zeigt den Leuten, dass die Legion nicht unbesiegbar ist.", sourceObjective = "Schließt einen Legionsinvasionspunkt auf der Weltstufe Heroisch ab.", completion = "Die Macht, über die Ihr und Euer Artefakt verfügt, konnte einer Invasion der Legion Einhalt gebieten. Doch habt Ihr das bewirkt, oder war es Euer Artefakt? Dazu werde ich weitere Informationen benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91440] = { id = 91440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Held der Verheerten Inseln", description = "Heldentaten sind eine Frage der Perspektive. Was <einem mächtigen Helden/einer mächtigen Heldin> wie Euch banal erscheint, könnte für jemand anderen die Welt verändern.\n\nSucht Bedürftige auf und helft ihnen bei den Aufgaben, die sie für wichtig erachten. Dies wird Eure Legende wachsen lassen.", sourceObjective = "Schließt 5 Quests auf der Weltstufe Heroisch ab.", completion = "Euer Name geistert in den Köpfen der Leute herum und ist am Lagerfeuer in aller Munde. Je mehr Eure Legende wächst, desto mächtiger wird Euer Name. Aber kann die Macht eines Namens die Macht des dazugehörigen Artefakts überschatten? Das ist die alles entscheidende Frage.", sourceObjectiveStatus = "unverified-source-field" }
quests[91441] = { id = 91441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Große Invasionspunkte (Heroisch)", description = "Sobald die Legion Chaos und Verwirrung gestiftet hat, beginnt sie ihren eigentlichen Angriff. Riesige Invasionsrisse öffnen sich und die Legion marschiert in Scharen daraus hervor. Die Verteidiger sind zerstreut und befassen sich mit kleineren Rissen, also sind sie an keinem dieser Orte zahlreich genug vertreten, um die Legion aufzuhalten.\n\nIn solchen Zeiten brauchen wir Champions wie Euch am dringendsten.\n\nSucht Euch eine der großen Invasionen der Legion und bekämpft sie mit allem, was Ihr habt.\n\nZeigt den Leuten, dass man mit genug Entschlossenheit sogar den Weltuntergang aufhalten kann.", sourceObjective = "Schließt einen großen Legionsinvasionspunkt auf der Weltstufe Heroisch ab.", completion = "Es ist so, wie ich vorhergesagt hatte. Ihr konntet eine gewaltige Invasion der Legion aufhalten. Nicht Ihr habt das vollbracht, und Euer Artefakt auch nicht. Es war die Kombination aus beidem, die siegreich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[91442] = { id = 91442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biokuppel Al'dani", description = "Wir haben Kunde von Ve'nari erhalten, dass die Ödnisbewohner dem Fortschritt auf K'aresh noch immer im Weg stehen. Sie bedrohen die erfolgversprechendste Biokuppel.\n\nDer Wiederaufbau auf K'aresh dürfen nicht unterbrochen werden.\n\nSetzt dieser Ineffizienz ein Ende.", sourceObjective = "Biergoth verlangt, dass Ihr die Seelenschreiberin in der Biokuppel Al'dani zur Rechenschaft zieht.", completion = "Das ist ein vielversprechender Anfang unserer neuen Beziehungen mit K'aresh.\n\nGute Arbeit, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[91443] = { id = 91443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien für Fortgeschrittene, Selten", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um seltene Gegner, also konzentriert Euch darauf, solche zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 4 seltene Gegner auf der Weltstufe Heroisch.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91444] = { id = 91444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien für Fortgeschrittene, Elite", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Elitegegner, also konzentriert Euch darauf, solche zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 5 Elitegegner auf der Weltstufe Heroisch.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91445] = { id = 91445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien für Fortgeschrittene, Allgemein", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDas hier ist eine allgemeine Untersuchung, also könnt Ihr Euch Eure Kampfgegner frei aussuchen, damit wir Grundwerte für Eure Fähigkeiten bekommen.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 75 Gegner auf der Weltstufe Heroisch.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91446] = { id = 91446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien für Fortgeschrittene, Seltene Elite", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um seltene Elitegegner, also konzentriert Euch darauf, solche zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet einen seltenen Elitegegner auf der Weltstufe Heroisch.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91447] = { id = 91447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien für Fortgeschrittene, Dämonologie", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Dämonologie, also konzentriert Euch darauf, dämonische Gegner zu bekämpfen, damit wir Eure Fähigkeiten besser verstehen können.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 30 Dämonen auf der Weltstufe Heroisch.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91448] = { id = 91448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Heroische Schrecken der Verheerten Inseln", description = "Es ist an der Zeit, Euch und Euer Artefakt auf die Probe zu stellen.\n\nSucht Euch einen Schrecken der Verheerten Inseln und besiegt ihn.\n\nIch bin mir sicher, dass Ihr uns unabhängig vom Ergebnis viel zu denken geben werdet. Ich werde hochinteressiert zusehen.", sourceObjective = "Tötet einen Weltboss auf der Weltstufe Heroisch.", completion = "Ein faszinierendes Ergebnis, {name}. Das gewährt uns dringend benötigte Daten für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[91449] = { id = 91449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien für Fortgeschrittene, Ermächtigung", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nWir untersuchen hier die ermächtigten Gegner in der experimentellen, fragmentierten Zeitlinie. Wir müssen feststellen, wie Eure Fähigkeiten auf entsetzliche Veränderungen reagieren.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 10 ermächtigte Gegner auf der Weltstufe Heroisch.", completion = "Sehr gut, {name}. Moratari wird entzückt sein, diese neuen Datenpunkte zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91451] = { id = 91451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stängelmarkt", description = "<Die geheimnisvolle Pflanze pulsiert in Eurer Hand. Jemand in Tazavesh wird wissen, was damit zu tun ist. Sucht auf dem Verhüllten Markt nach einem Interessenten.>", sourceObjective = "Bringt Eure Entdeckung zu Om'mit in Tazavesh.\n\nBereitgestellter Gegenstand:", completion = "<Om'mit wendet die Pflanze in seinen Händen.>\n\nEin leerenerfüllter Stängel aus einem toten Ödland? Das ist für Euch komplett nutzlos. Ich nehme ihn Euch gerne im Tausch für Pflanzen mit... vertrauteren Eigenschaften ab.\n\nAndere Mitglieder des Kartells Om auf dem Verhüllten Markt könnten ebenfalls mit Euch handeln wollen, wenn Ihr welchen begegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[91454] = { id = 91454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasenverlorener Abenteurer", description = "Das Tagebuch ist mit Schleim und Speichel bedeckt und enthält einen unvollständigen Eintrag eines vorherigen Phasentauchers.\n\n<Tag 27\n\nDer ungebundene Raum ist größer als ich erwartet habe und birgt Monster, die stärker sind als alles, was ich auf K'aresh gesehen habe. \n\nIn der Nähe ist eine Höhle, die ich morgen erkunden werde. Sie ist voll von phasenveränderter Essenz. Das könnte hilfreich sein, um die örtliche Ökologie besser zu verstehen.>\n\nForscherin Essarae wäre daran sicherlich interessiert.", sourceObjective = "Bringt das Tagebuch zu Forscherin Essarae in Shan'dorah.", completion = "<Essarae schlägt eine zufällige Seite im Tagebuch auf.>\n\nHierin befindet sich eine Menge Wissen über den ungebundenen Raum. Ich würde gerne mehr davon lesen. \n\nVielen Dank für Eure Hilfe bei meiner Suche.", sourceObjectiveStatus = "unverified-source-field" }
quests[91459] = { id = 91459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Omega: Ein wandelnder Schatten", description = "Champion, könnt Ihr mich hören? Es gibt einen Translokator, den die Schattenwachen für ihre Frachttransporte verwenden. Er kann Euch direkt zu ihrem Posten unter der Manaschmiede bringen. Eine Falle, mit der sie niemals rechnen werden!\n\nNatürlich gibt es einen Haken an der Sache: Uns fehlen die nötigen Berechtigungen, um ihre Versorgungslinien zu nutzen... Die müsstet Ihr uns noch besorgen. Erledigt das ranghöchste Mitglied der Schattenwache, das Ihr finden könnt, kehrt mit seinem Ausweis zurück, und wir fälschen für Euch eine Fahrkarte an die Front. Ohne Rückfahrt!", sourceObjective = "Besiegt Nexuskönig Salhadaar in der Manaschmiede Omega auf dem Schwierigkeitsgrad Normal oder höher.", completion = "Das ist wirklich ranghoch, {name}! Sobald ich meine Magie gewirkt habe, gehört der Translokator so gut wie uns. Nächster Halt: Feindesland!", sourceObjectiveStatus = "unverified-source-field" }
quests[91460] = { id = 91460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Omega: Ein wandelnder Schatten", description = "Champion, könnt Ihr mich hören? Es gibt einen Translokator, den die Schattenwachen für ihre Frachttransporte verwenden. Er kann Euch direkt zu ihrem Posten unter der Manaschmiede bringen. Eine Falle, mit der sie niemals rechnen werden!\n\nNatürlich gibt es einen Haken an der Sache: Uns fehlen die nötigen Berechtigungen, um ihre Versorgungslinien zu nutzen... Die müsstet Ihr uns noch besorgen. Erledigt das ranghöchste Mitglied der Schattenwache, das Ihr finden könnt, kehrt mit seinem Ausweis zurück, und wir fälschen für Euch eine Fahrkarte an die Front. Ohne Rückfahrt!", sourceObjective = "Besiegt Nexuskönig Salhadaar in der Manaschmiede Omega auf dem Schwierigkeitsgrad Heroisch oder höher.", completion = "Das ist wirklich ranghoch, {name}! Sobald ich meine Magie gewirkt habe, gehört der Translokator so gut wie uns. Nächster Halt: Feindesland!", sourceObjectiveStatus = "unverified-source-field" }
quests[91461] = { id = 91461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Omega: Ein wandelnder Schatten", description = "Champion, könnt Ihr mich hören? Es gibt einen Translokator, den die Schattenwachen für ihre Frachttransporte verwenden. Er kann Euch direkt zu ihrem Posten unter der Manaschmiede bringen. Eine Falle, mit der sie niemals rechnen werden!\n\nNatürlich gibt es einen Haken an der Sache: Uns fehlen die nötigen Berechtigungen, um ihre Versorgungslinien zu nutzen... Die müsstet Ihr uns noch besorgen. Erledigt das ranghöchste Mitglied der Schattenwache, das Ihr finden könnt, kehrt mit seinem Ausweis zurück, und wir fälschen für Euch eine Fahrkarte an die Front. Ohne Rückfahrt!", sourceObjective = "Besiegt Nexuskönig Salhadaar in der Manaschmiede Omega auf dem Schwierigkeitsgrad Mythisch oder höher.", sourceObjectiveStatus = "unverified-source-field" }
quests[91467] = { id = 91467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inkarnationen auf dem Vormarsch", description = "Ich dachte mir schon, dass ich Euch hier finden würde, {name}. Ich bringe Nachricht von den anderen Aspekten und meinen Spähern.\n\nDie Inkarnationen sind auf dem Vormarsch. Ich weiß nicht, was sie planen, aber Ihr solltet Kenntnis von ihren Aktionen haben.", sourceObjective = "Sprecht mit Glutthal, um mehr über die Inkarnationen herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[91476] = { id = 91476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien", description = "<Mein Guter/Meine Gute>, wir haben einige neue Werkzeuge fertiggestellt, die der Schattenwache ordentlich weh tun sollten. Kommt vorbei und lasst sie uns gemeinsam ausprobieren.", sourceObjective = "Meldet Euch bei Zo'turu am Schattenpunkt.", completion = "Hört gut zu: Dank unserer Informanten in der Manaschmiede haben wir eine Technologie entdeckt, die Euch helfen kann, sie stillzulegen. Dieser Transporter wurde darauf eingestellt, Eure Seele für kurze Zeit hierher zu projizieren, sodass Ihr auf alles zugreifen könnt, was Ihr benötigt. Aber seid gewarnt: Die Energiefelder von Omega sind außerordentlich stark und werden Eure Essenz schnell wieder zurück an die Position Eures Körpers reißen. Man sagt, das sei... ziemlich schmerzhaft. Trotzdem, jeder Vorteil zählt. Beeilt Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[91477] = { id = 91477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien II", description = "Unser Wissen über die Technomantie wächst. Verbessern wir Eure Bewaffnung in der Manaschmiede.", sourceObjective = "Meldet Euch bei Zo'turu am Schattenpunkt.", completion = "Hört gut zu: Wir haben neue Technologie beschafft, die Euch helfen kann, die Schattenwache zu besiegen. Macht das Beste draus.", sourceObjectiveStatus = "unverified-source-field" }
quests[91478] = { id = 91478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien III", description = "Unser Wissen über die Technomantie wächst. Verbessern wir Eure Bewaffnung in der Manaschmiede.", sourceObjective = "Meldet Euch bei Zo'turu am Schattenpunkt.", completion = "Hört gut zu: Wir haben neue Technologie beschafft, die Euch helfen kann, die Schattenwache zu besiegen. Macht das Beste draus.", sourceObjectiveStatus = "unverified-source-field" }
quests[91479] = { id = 91479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien IV", description = "Unser Wissen über die Technomantie wächst. Verbessern wir Eure Bewaffnung in der Manaschmiede.", sourceObjective = "Meldet Euch bei Zo'turu am Schattenpunkt.", completion = "Hört gut zu: Wir haben neue Technologie beschafft, die Euch helfen kann, die Schattenwache zu besiegen. Macht das Beste draus.", sourceObjectiveStatus = "unverified-source-field" }
quests[91480] = { id = 91480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien V", description = "Wir haben eine letzte Verbesserung für Euch! Kommt vorbei, und wir machen Euch stärker als Ihr je wart!", sourceObjective = "Meldet Euch bei Zo'turu am Schattenpunkt.", completion = "Damit seid Ihr so mächtig wie unsere bescheidene Bande Euch machen kann. Möge es Euch im Kampf gegen Dimensius dienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[91481] = { id = 91481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwindigkeitsschröpfer", description = "Großartige Arbeit soweit! Wir haben einige Technik, die bei einem Angriff auf die Manaschmiede nützlich sein könnte.", sourceObjective = "Meldet Euch bei Zo'ropo am Schattenpunkt.", completion = "Zo'ropo bringt Euch eine neue Waffe. Nutzt sie, um die arkane Strahlung der Manaschmiede aufzufangen, und wendet ihre Energie gegen sie selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[91482] = { id = 91482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwindigkeitsschröpfer II", description = "Wir haben eine Möglichkeit gefunden, um den Geschwindigkeitsschröpfer zu optimieren. Kommt ins Hauptquartier, dann gebe ich Euch einen Schub!", sourceObjective = "Meldet Euch bei Zo'ropo am Schattenpunkt.", completion = "Doppelt so schnell und doppelt so stabil. Macht sie fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[91483] = { id = 91483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Großrechner hacken", description = "Unsere Saboteure haben großartige Fortschritte beim Hacken von Omegas Sicherheitssystemen gemacht. Kommt vorbei, dann erzähle ich Euch, was wir erfahren haben.", sourceObjective = "Meldet Euch bei Zo'ropo am Schattenpunkt.", completion = "Im Inneren der Manaschmiede gibt es Konsolen, die den Energiefluss in der Anlage aufrechterhalten. Wir haben die Sicherheitsvorkehrungen der ersten Konsole geknackt, sodass Ihr die Gegner bei Loom'ithar und Seelenbinderin Naazindrhi gegen sich selbst wenden könnt. Ihr könnt nur eine Konsole benutzen, aber dieser Sabotageakt verschafft Euch einen Vorteil im Kampf. Viel Glück da drin!", sourceObjectiveStatus = "unverified-source-field" }
quests[91484] = { id = 91484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schmiedeweber hacken", description = "Wir haben weitere Fortschritte in der Überwindung der Verteidigung der Manaschmiede gemacht. Kehrt ins Hauptquartier zurück, dann verschaffe ich Euch Zugang.", sourceObjective = "Meldet Euch bei Zo'ropo am Schattenpunkt.", completion = "Wir haben eine Schwachstelle in der Werkstatt von Schmiedeweber Araz gefunden, die Euch Zugang zu einer weiteren Konsole in der Nähe verschafft. Bleibt am Ball. Wir geben Euch Bescheid, sobald die ganze Anlage unter unserer Kontrolle ist. Viel Erfolg bei der Jagd!", sourceObjectiveStatus = "unverified-source-field" }
quests[91485] = { id = 91485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Planeten hacken", description = "Wir sind drin. Wir haben die volle Kontrolle über die Sicherheitssysteme der Manaschmiede Omega. Wenn Ihr das nächste Mal vorbei kommt, bringe ich Euch auf den neuesten Stand.", sourceObjective = "Meldet Euch bei Zo'ropo am Schattenpunkt.", completion = "Die Sicherheitssysteme der Manaschmiede Omega sind nun unter unserer direkten Kontrolle. Dank des Schadens, den Ihr dort angerichtet habt, können wir Euch Zugang zu Konsolen verschaffen, die bis zu Salhadaar und darüber hinaus reichen. Außerdem haben wir dafür gesorgt, dass Ihr jede Konsole benutzen könnt, auf die Ihr stoßt. Mehr kann ich für Euch nicht tun. Geht hinein und beendet den Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[91486] = { id = 91486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Äther eingestimmt", description = "Hallo! Ich habe wertvolle Informationen darüber, wie sich der Kontakt mit dem Manafluss von Omega auf Euch auswirkt. Lasst uns am Schattenpunkt darüber sprechen, sobald Ihr Zeit habt.", sourceObjective = "Meldet Euch bei Ba'choso am Schattenpunkt.", completion = "Meine Forschungen zeigen, dass wir dank des Einflusses der Reshiiwickel auf Eure physische Form die mächtigen Manawogen und Reaktoren in Omega zu Eurem Vorteil nutzen können! Auch wenn es nur ein Bruchteil Eurer Kraft ist, scheint es, als würden die arkanen Verbesserungen an Eurer Ausrüstung in ihrer Nähe noch mächtiger werden. Das verlangt nach weiteren Tests...", sourceObjectiveStatus = "unverified-source-field" }
quests[91487] = { id = 91487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Mannschaft", sourceObjective = "Wir haben gemeinsam große Fortschritte im Kampf gegen die Schattenwache gemacht. Für Eure Opfer und Mühen betrachten meine Kollegen und ich Euch nun als einen der Unsrigen. Bitte nehmt diese modifizierte Gleitscheibe als Zeichen unseres Dankes an. Möge sie Euch sicher zu Eurem nächsten Auftrag bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91489] = { id = 91489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Begleiter", sourceObjective = "<Der Schnurrer blickt Euch liebevoll an. Zum ersten Mal, seit Ihr in K'aresh angekommen seid, scheint er Eure Aufmerksamkeit tatsächlich zu *genießen*. Als er sich näher an Euch schmiegt, bestätigt ein leises, weiches Miauen Eure Vermutung: Er möchte sich Euch anschließen. Zumindest vorerst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[91522] = { id = 91522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung aus dem Chaos", sourceObjective = "Sprecht mit Moratari und beantwortet ihre Fragen.", completion = "Welch faszinierender Einblick in diese Ereignisse.\n\nIch habe sie aus der Ferne mitangesehen, aber es ist viel spannender, die Version zu hören, die Ihr unmittelbar erlebt habt.\n\nDanke, dass Ihr mich daran teilhaben lasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[91525] = { id = 91525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjagd: Loom'ithar", description = "Laut unseren Berichten handelt es sich um eine kolossale Bestie in der Manaschmiede, die für die Herstellung des Stoffs verantwortlich sein soll, der der Schattenwache ihre Gestalt verleiht. Erledigt sie, um ihre Produktionsfähigkeiten einzuschränken und weitere Verstärkung ihrer Ränge zu verhindern. Ach, und Ba'choso will, dass Ihr ihm was von der Seide mitbringt - er kann daraus vielleicht etwas Nützliches machen.", sourceObjective = "Besiegt Loom'ithar in der Manaschmiede Omega auf einem beliebigen Schwierigkeitsgrad.", completion = "Solch eine hochwertige Qualität habe ich noch nie gesehen! Ich mache mich sofort ans Werk. Lasst uns nur vorher noch über Eure Bezahlung sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91526] = { id = 91526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjagd: Schmiedeweber Araz", description = "Ich hoffe, Euer Angriff läuft gut. Es ist Zeit, dass Ihr den Schmiedeweber loswerdet. Mit seiner meisterlichen Technomantie überwacht er sowohl die Produktion der Manaschmiede... als auch das Ritual, mit dem Dimensius auf diese Ebene zurückgeholt werden soll. Seine Werkstatt wird tief im Inneren liegen und schwer bewacht sein. Aber ihn zu erledigen, sollte ihren Wiederbelebungsplänen endgültig ein Ende bereiten.", sourceObjective = "Besiegt Schmiedeweber Araz in Manaschmiede Omega auf einem beliebigen Schwierigkeitsgrad.", completion = "{name}... Damit hätte ich rechnen müssen. Seine Hingabe für Dimensius war grenzenlos, und er hatte sicherlich Vorkehrungen getroffen, um den Abschluss des Rituals sicherzustellen. Wir müssen uns einen anderen Angriffswinkel suchen. Wir haben einige Trümmer seiner inneren Zuflucht gefunden, die hier gelandet sind. Wenn Ihr den nötigen Grips besitzt, können wir Euch zeigen, wie Ihr sie für Eure eigenen Zwecke einsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91527] = { id = 91527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjagd: Die Seelenjäger", description = "Seid vorsichtig in der Ödnis. Die Späher berichten von einem Dämonenjäger-Trio, das südlich der Manaschmiede trainiert. Einer von Ihnen besitzt eine Macht, wie wir sie noch nie gesehen haben. Ihr könnt ihnen ausweichen, wenn Ihr wollt, aber wenn Ihr sie ignoriert, könnten sie Euch später in den Rücken fallen. Ich würde vorschlagen, sie nach Möglichkeit auszuschalten sowie uns einige Proben ihrer neuartigen Kraft zu bringen.", sourceObjective = "Besiegt die Seelenjäger in der Manaschmiede Omega auf einem beliebigen Schwierigkeitsgrad.", completion = "So eine Seelenenergie habe ich noch nie gesehen. Wir können ihnen zwar nicht zu ihrer einstigen Form zurückverhelfen, aber ich glaube, Ihr könnt diese Runen nutzen, um Euch sogar über den Tod hinaus zu stärken. Nehmt sie, aber nutzt sie wohlüberlegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91528] = { id = 91528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjagd: Schrecken der Schmiede", description = "Inzwischen habt Ihr bestimmt die eine oder andere Elite der Manaschmiede gesehen, die zu Salhadaars Hilfe gekommen ist. Ich schicke Euch eine Liste mit Namen. Wenn Ihr Euch auf diese Ziele konzentriert, könnt Ihr vielleicht etwas Nützliches für Euren Angriff erbeuten.", sourceObjective = "Besiegt mächtige Elitegegner in der Manaschmiede Omega auf einem beliebigen Schwierigkeitsgrad.", completion = "Gut gemacht, Champion. Die Ressourcen, die sie gehortet haben, werden Euren Begleitern viel besser nützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91529] = { id = 91529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjagd: Nexuskönig Salhadaar", description = "Salhadaars Stunde hat geschlagen. So selbstsicher er auch auf seiner Leerenschwinge posiert, er verzweifelt zu Füßen des alles Verschlingenden. Die Armee unter seinem Kommando kann gegen Eure Macht nicht bestehen. Streckt ihn nieder.", sourceObjective = "Besiegt Nexuskönig Salhadaar in der Manaschmiede Omega auf einem beliebigen Schwierigkeitsgrad.", completion = "Obwohl es nicht das Ende war, das er verdient hätte, werden wir seine Niederlage gleichsam feiern. Sucht Zo'ropo auf, um Eure wohlverdiente Belohnung zu erhalten. Euch gebührt meine ewige Dankbarkeit für seine Absetzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[91530] = { id = 91530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Auge, Zahn um Zahn", sourceObjective = "Ähem, diese kleine Kreatur hier stand plötzlich vor unserem Versteck und brabbelte so Sachen wie: \"Ihr habt meinen Vater getötet. Jetzt seid Ihr des Todes!\". Zwar wissen wir nicht über alles Bescheid, was in der Manaschmiede vor sich geht, aber sicher könnt Ihr und... dieser junge Mann das wie Erwachsene klären? Idealerweise fernab unseres Hauptquartiers und ohne Geschrei?\n\nEs handelt sich sicher nur um ein Missverständnis. Ich wünsche Euch viel Erfolg dabei, diese Angelegenheit zu regeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[91539] = { id = 91539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein strahlendes Echo", description = "<In Eurer Hand haltet Ihr eine kleine Azeritkugel. Ihr Licht ist gleichmäßig und hell, doch der Klang, den sie aussendet, ist klagend und sehnsüchtig. Sie zieht ganz leicht an Euch.>", sourceObjective = "Bringt das strahlende Echo zu einer Weltenseelenerinnerung und lasst es dann frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[91612] = { id = 91612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung" }
quests[91613] = { id = 91613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beförderung bei der ewigen Forschung: Zeitassistenz", sourceObjective = "{name}, Ihr habt uns mit unserer Forschung hervorragend weitergeholfen. Ich denke, Ihr habt Euch eine Beförderung verdient.\n\nAb jetzt könnt Ihr mehr Forschungsaufgaben gleichzeitig annehmen.\n\nEs ist schon ironisch, dass wir irgendwie nie genug Zeit haben, nicht wahr? Nutzt Eure Zeit hier gut. Sorgt dafür, dass ich es nicht bereue, Euch diese Macht gegeben zu haben.Diese Questreihe schaltet Folgendes frei:", sourceObjectiveStatus = "unverified-source-field" }
quests[91614] = { id = 91614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fokussierte Energien", description = "Zusätzlich zu den Alptraumsplittern benötigen wir auch noch Blut von Sargeras, um das Portal zum Riss von Aln zu reaktivieren.\n\nDieses seltene Reagenz erhält man im Gebiet der Verheerten Inseln. Angeblich sollen ein paar Gesandte nach erfahrenen Abenteurern suchen und dieses Reagenz als Belohnung anbieten.", sourceObjective = "Sammelt 3 Proben des Bluts von Sargeras.", completion = "Ausgezeichnet, Erzdruide. Damit lässt sich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[91615] = { id = 91615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durst nach Blut", sourceObjective = "Endlich habe ich genug Blut von Sargeras, um meine Kreationen zu verstärken! Schon bald werdet Ihr sehen, was ich wirklich zu erschaffen in der Lage bin...\n\nUnd jetzt muss ich Euch bitten, mich bei der Arbeit allein zu lassen... Es gibt so viel zu tun und nicht mehr allzu viel Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[91616] = { id = 91616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Reagenzien", description = "Die Schildwachen kennen eine vertrauenswürdige und talentierte Verzauberin, die sich auf Verzauberungen gegen Dämonen spezialisiert hat.\n\nSie stellt ihre Dienste den Schildwachen kostenlos zur Verfügung, aber sie benötigt gewisse Reagenzien, um ihre Verzauberungen vornehmen zu können.", sourceObjective = "Sammelt die erforderlichen Reagenzien.", completion = "Das sollte genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91618] = { id = 91618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eins nach dem anderen", description = "In letzter Zeit habe ich mit dem Erz dieses Landes gearbeitet, das Leystein genannt wird. Ich habe herausgefunden, dass es von bemerkenswerter Stärke und Haltbarkeit ist. Wir werden hierfür eine Menge davon brauchen.\n\nEs gibt noch Teufelsschiefer, aber der ist wahrscheinlich zu verderbt für das, was Ihr mit diesem Geschirr vorhabt.\n\nWisst Ihr, ich verziere meine Arbeiten auch gerne mit etwas Funkelndem wie einem Edelstein. Ich habe gehört, dass die Elfen von Suramar besonders schöne Exemplare haben. Vielleicht könntet Ihr einen davon für dieses Projekt besorgen.", sourceObjective = "Beschafft 1 Brocken Leysteinerz und einen suramarischen Saphir.", progress = "Ich bezweifle, dass Ihr Schwierigkeiten haben werdet, Leystein zu bekommen, doch der Saphir dürfte etwas schwieriger zu beschaffen sein.", completion = "Ihr habt alles! Dann können wir ja jetzt Euer Geschirr aufwerten.\n\nSagt niemals, ein Schmied könne die Arbeit eines Lederverarbeiters nicht aufwerten, sage ich immer. Ich meine, niemals. Ich meine... Nun, Ihr wisst schon, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[91619] = { id = 91619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut von Sargeras", description = "Wir werden ein mächtiges Reagenz benötigen, um die Magie in unsere Waffen und Rüstungen zu binden. Das Blut von Sargeras ist ein seltenes Material, mit dem genau dies gelingen könnte.\n\nWir brauchen dafür aber eine ganze Menge. Bringt mir also so viel davon, wie Ihr nur könnt.", sourceObjective = "Sammelt Blut von Sargeras.", completion = "Ja, das ist genau, was wir brauchen, um unsere Vorbereitungen abzuschließen. Die Beschaffung war sicherlich nicht einfach. Ich danke Euch, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[91620] = { id = 91620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfoggers zumutbare Anfrage", description = "Ach, was erlaubt sich der kleine grüne Giftzwerg eigentlich? Marin Noggenfogger erpresst uns. Wenn wir seine \"preislich absolut zumutbare Materialanfrage\" nicht erfüllen, verweigert er den weiteren Zugang zum Tiegel.\n\nMarin verlangt enorme Mengen Aethril. Er meinte, Ihr hättet ihm kürzlich ein Messer an die Kehle gehalten und er revanchiert sich jetzt einfach.\n\nNatürlich kann ich ihn auch einfach unschädlich machen, wenn Euch das lieber wäre.", sourceObjective = "Sammelt Aethril.", completion = "Wir tragen uns nichts nach, ja? Geschäft ist Geschäft, und das Geschäft brummt. Ich habe eine Gelegenheit gewittert und wahrgenommen. Genau wie Ihr.\n\nAls Zeichen meiner Verbundenheit zu Eurer kleinen Organisation und als Geste guten Willens habt Ihr hier eine Probe des Produkts. Zauberhaft. Prost!", sourceObjectiveStatus = "unverified-source-field" }
quests[91621] = { id = 91621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Gelüste", sourceObjective = "<Ma'haat der Unbeugsame schluckt gierig das Blut von Sargeras herunter, während er spricht.>\n\nJa... dasch ischt... genau rischtisch. Dasch Ei gehört Eusch.", sourceObjectiveStatus = "unverified-source-field" }
quests[91624] = { id = 91624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funke des Sternenlichts", description = "Eine Vision aus Sternenlicht durchdringt Eure Gedanken.\n\nHüter Khubon könnte mehr über die abgesplitterten Funken des Sternenlichts wissen.", sourceObjective = "Sprecht mit Hüter Khubon in Dornogal.", completion = "Das ist ein abgesplitterter Funke des Sternenlichts.\n\nJede Woche wird Euch einer dieser Splitter auf Euren Abenteuern begegnen. In seinem jetzigen Zustand ist er ziemlich nutzlos, aber durch die Kombination mit einem anderen Splitter wird ihm Macht verliehen. Solche Reagenzien sind formbar, robust und bei vielen Handwerkern sehr begehrt.\n\nKombiniert zwei dieser Splitter, um ein einziges Handwerksmaterial herzustellen, mit dem Ihr einem Gegenstand Expertise verleihen könnt, die die Fähigkeiten von Sterblichen übersteigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91631] = { id = 91631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epochaler Fortschritt", sourceObjective = "Eure Macht wächst an, {name}.\n\nBitte nehmt dieses Zeichen unserer Dankbarkeit für Eure Unterstützung bei unserer Forschung. Möge es mit jeder Version von Euch nachhallen, die in Fragmenten dieser Zeitlinie existiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[91632] = { id = 91632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende einer epochalen Reise", sourceObjective = "Ihr habt Euer volles Potenzial erreicht, {name}. Oder doch nicht? Vielleicht ist dies erst der Anfang Eurer Reise durch diese Epoche.\n\nBitte nehmt dieses Zeichen unserer Dankbarkeit für Eure Unterstützung bei unserer Forschung. Möge es mit jeder Version von Euch nachhallen, die in Fragmenten dieser Zeitlinie existiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[91639] = { id = 91639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht Euch Eure Legende zu eigen", description = "Ich werde Eure Fortschritte im Auge behalten und Eure Abenteuer mit diesem Artefakt sehr interessiert beobachten.\n\nSobald Ihr Euch die Macht Eurer Legende zu eigen gemacht habt, würde ich gerne Eure Ansichten dazu hören, wie wichtig Euer Artefakt auf Eurer Reise war.", sourceObjective = "Sprecht mit Eternus auf dem Ewigen Basar in Dalaran, nachdem Ihr Euch Eure Legende zu eigen gemacht habt.", progress = "Vor uns liegt ein Pfad des Lernens und der Entdeckungen. Lasst ihn uns gemeinsam beschreiten.", completion = "Ihr seid stärker geworden, aber Euer Artefakt ist noch stärker.\n\nOffenbar bestätigt sich meine Hypothese: Artefakte sind der Schlüssel dazu, Azeroth zu beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91695] = { id = 91695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inkarnationen aufspüren", description = "Nun, da Iridikron sich anscheinend unseren Blicken entzogen hat, müssen wir unsere Aufmerksamkeit Fyrakk und Vyranoth zuwenden.\n\nMerithra und der grüne Drachenschwarm sind ihm auf der Spur.\n\nSie haben bei dieser Aufgabe Hilfe von Shandris Mondfeder erhalten.\n\nSie erwartet Euch in Valdrakken. Shandris wird Eure Hilfe bei den bevorstehenden Ereignissen brauchen.", sourceObjective = "Findet Shandris Mondfeder in Valdrakken.", sourceObjectiveStatus = "unverified-source-field" }
quests[91721] = { id = 91721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertrefft Eure Legende", description = "Die Artefakte sind zwar wichtig, aber wir dürfen nicht die Macht der Individuen vernachlässigen, die sie führen.\n\nSetzt Euren Kampf gegen die Legion fort. Werdet stark. Stärker, als Ihr es je für möglich gehalten habt.\n\nDann werden wir die Macht Eurer Legende mit der des Artefakts vergleichen.", sourceObjective = "Sprecht mit Eternus auf dem Ewigen Basar in Dalaran, nachdem Ihr Eure Legende übertroffen habt.", progress = "Die Person, die ein Artefakt führt, ist schon von Bedeutung. Aber wie sehr? Welche Legende ist die größere?\n\nLasst uns das gemeinsam herausfinden.", completion = "Ich gebe es zu. Es ist eine freudige Überraschung, dass ich mich geirrt habe. Eure Macht ist gewachsen und ich kann nicht sicher sagen, welche von beiden stärker ist: die Eure, oder die Eurer Waffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[91722] = { id = 91722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschafft eine neue Legende", description = "Jetzt ist klar, dass die Person, die das Artefakt trägt, mindestens so wichtig ist wie das Artefakt selbst.\n\nVielleicht liegt es an der Natur der Sterblichkeit, dass das Individuum durch die Linse der Geschichte an Wichtigkeit verliert. Ein Artefakt ist für die Ewigkeit, doch diejenigen, die es tragen, vergehen.\n\nDoch keine Flamme, die hell erstrahlt, kann für immer brennen.\n\nIch wünsche mir, dass Ihr so hell erstrahlt, wie Ihr nur könnt. Verstärkt Euer Artefakt und schafft so Eure eigene Legende.", sourceObjective = "Sprecht mit Eternus auf dem Ewigen Basar in Dalaran, nachdem Ihr eine neue Legende erschaffen habt.", progress = "Ein Artefakt kann sich schlecht selbst verstärken. Seine Macht wächst nur, wenn die Person, die es trägt, große Taten mit ihm vollbringt.", completion = "Wie erstaunlich.\n\nDie Antwort liegt in der Natur der endlichen Existenz selbst.\n\nDie Sterblichkeit ist gleich einer hell brennenden Flamme. Sie kann nur strahlen, weil ihr Feuer einst erlöschen wird. Sie wird nicht von der schrecklichen Bürde der Unendlichkeit beschwert.\n\nWählt auch Ihr Euren Heldenmoment weise, {name}, und nichts wird Euch je aufhalten können. Nicht einmal die Zeit selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[91728] = { id = 91728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar befreit", sourceObjective = "Sprecht mit Moratari und beantwortet ihre Frage.", completion = "Äußerst interessant.\n\nIch werde das natürlich als Datenpunkt aufzeichnen.\n\nWenn ich weiß, wie Ihr Entscheidungen trefft, kann ich zukünftig besser informierte Hypothesen aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91729] = { id = 91729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armeen versammelt", sourceObjective = "Sprecht mit Moratari und beantwortet ihre Frage.", completion = "Neue Einblicke sind für unsere Bemühungen hier sehr wertvoll, {name}.\n\nDanke, dass Ihr mir Eure gewährt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91730] = { id = 91730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth gerettet", sourceObjective = "Sprecht mit Moratari und beantwortet ihre Frage.", completion = "Zu viele Geschichten halten WAS, WARUM, WIE und WANN fest. Aber die Frage WER bleibt über reine Namen hinaus unbeantwortet.", sourceObjectiveStatus = "unverified-source-field" }
quests[91768] = { id = 91768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwitzendes Mana", description = "Standardbeschreibung", sourceObjective = "Questlog-Beschreibung\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[91780] = { id = 91780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astrale Tiefen", description = "In den Tiefen gibt es sogar noch mehr zu tun, {name}!\n\nTrefft mich in Dornogal. Es gibt viel zu bereden!", sourceObjective = "Trefft Euch mit Brann Bronzebart in Dornogal.", completion = "Schön, dass Ihr hier seid! Wir haben jede Menge zu bereden.", sourceObjectiveStatus = "unverified-source-field" }
quests[91781] = { id = 91781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saisonale Erinnerung", description = "Wir decken noch mehr Geheimnisse in den Tiefen auf! \n\nZunächst einmal sollten wir Euch aber auf den neuesten Stand bringen.\n\nDanach brauche ich Eure Hilfe bei einem klitzekleinen Problemchen...", sourceObjective = "Erfahrt mehr über Saison 3 der Tiefen in den Tiefenforscherdokumenten und kauft Euch dann Vorräte bei Reno Jackson und Sir Finley Mrrgglton.", completion = "Gut, kommen wir zu dem klitzekleinen Problemchen, das ich vorhin erwähnt hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[91782] = { id = 91782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschlagnahmt!", description = "Ihr seid mittlerweile sicher schon dahintergekommen, um was es geht, {name}.\n\nMeine Kleidung, meine Werkzeuge, meine Kuriositäten! Alles, außer meinen Stiefeln und meinem Hut, die ich nicht noch einmal aufgeben werde.\n\nAlles von so einem Kartellschläger in Beschlag genommen, der meinte, ich wäre mit meinen Leerenlagerzahlungen im Verzug. Ist das zu glauben?\n\nKönntet Ihr dem alten Brann nicht aus der Patsche helfen? Ich bin sicher, wenn Ihr ihnen erklärt, dass es sich nur um ein Missverständnis handeln muss, dann geben sie mir meine hartverdiente Ausrüstung sicher zurück.\n\nOder zumindest meine Hose.", sourceObjective = "Beschafft Branns verlorene Ausrüstung zurück.", progress = "War es schon immer so windig in Dornogal?", completion = "Ich kann nicht glauben, dass das von Anfang an eine Finte war.\n\nEine Schande wegen der Kuriositäten, aber wenigstens hab ich meine Hose wieder!", sourceObjectiveStatus = "unverified-source-field" }
quests[91789] = { id = 91789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apocron" }
quests[91790] = { id = 91790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutallus" }
quests[91791] = { id = 91791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malificus" }
quests[91792] = { id = 91792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Si'vash" }
quests[91843] = { id = 91843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückblick: Die Vorbotin", description = "Um die Geschichte von The War Within zu verstehen, muss man mit der rätselhaften Entität beginnen, das als Vorbotin bekannt ist, und damit, wie die Champions von Azeroth die Wahrheit aufgedeckt haben...", sourceObjective = "Erfahrt im Geschichtsfolianten von den Ereignissen, die den Krieg im Inneren entfacht haben.", completion = "Alleria lüftete das Geheimnis der Vorbotin und offenbarte Xal'atath. Doch es dauerte nicht lange, bis die Vorbotin ihren Zug tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[91844] = { id = 91844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beförderung bei der ewigen Forschung: Ehrenchronograf", sourceObjective = "{name}, Ihr habt uns mit unserer Forschung hervorragend weitergeholfen. Ich denke, Ihr habt Euch eine Beförderung verdient.\n\nAb jetzt könnt Ihr mehr Forschungsaufgaben gleichzeitig annehmen.\n\nEs ist schon ironisch, dass wir irgendwie nie genug Zeit haben, nicht wahr? Nutzt Eure Zeit hier gut. Sorgt dafür, dass ich es nicht bereue, Euch diese Macht gegeben zu haben.Diese Questreihe schaltet Folgendes frei:", sourceObjectiveStatus = "unverified-source-field" }
quests[91845] = { id = 91845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beförderung bei der ewigen Forschung: Oberste Chronografieleitung", sourceObjective = "{name}, Ihr habt uns mit unserer Forschung hervorragend weitergeholfen. Ich denke, Ihr habt Euch eine Beförderung verdient.\n\nAb jetzt könnt Ihr mehr Forschungsaufgaben gleichzeitig annehmen.\n\nEs ist schon ironisch, dass wir irgendwie nie genug Zeit haben, nicht wahr? Nutzt Eure Zeit hier gut. Sorgt dafür, dass ich es nicht bereue, Euch diese Macht gegeben zu haben.Diese Questreihe schaltet Folgendes frei:", sourceObjectiveStatus = "unverified-source-field" }
quests[91846] = { id = 91846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beförderung bei der ewigen Forschung: Oberster Chronofragenermittler", sourceObjective = "{name}, Ihr habt uns mit unserer Forschung hervorragend weitergeholfen. Ich denke, Ihr habt Euch eine Beförderung verdient.\n\nAb jetzt könnt Ihr mehr Forschungsaufgaben gleichzeitig annehmen.\n\nEs ist schon ironisch, dass wir irgendwie nie genug Zeit haben, nicht wahr? Nutzt Eure Zeit hier gut. Sorgt dafür, dass ich es nicht bereue, Euch diese Macht gegeben zu haben.Diese Questreihe schaltet Folgendes frei:", sourceObjectiveStatus = "unverified-source-field" }
quests[91847] = { id = 91847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung" }
