quests[91849] = { id = 91849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung" }
quests[91855] = { id = 91855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Weltquests von K'aresh", description = "Nun weiß ich, dass die Helden Azeroths immer dorthin reisen, wo ihre Hilfe benötigt wird. K'aresh ist ein sonderbarer, entlegener Ort, aber unsere Verbündeten brauchen uns.\n\nBegebt Euch dorthin und unterstützt sie. Seht, was Ihr tun könnt, um den Astralen und den Mittlern eine Atempause zu verschaffen.", sourceObjective = "Schließt Weltquests auf K'aresh ab.", progress = "Unsere Verbündeten leisten tapfer auf einer toten und zerbrochenen Welt Widerstand. Ich bewundere sie.", completion = "Ihr macht Helden überall alle Ehre. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[91863] = { id = 91863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein erstes eigenes Zuhause", description = "Willkommen in der Nachbarschaft! Seht Euch gerne um und begutachtet die verfügbaren Grundstücke.\n\nSprecht mit dem Verwalter, um mehr darüber zu erfahren, wie Ihr zum Hausbesitzer werden oder Eure eigene Nachbarschaft gründen könnt.", sourceObjective = "Macht Euch mit der Nachbarschaft und den Bewohnern vertraut und findet dann einen Ort, um ein Haus zu bauen.", progress = "Habt Ihr das Heim Eurer Träume gefunden?", completion = "Glückwunsch zu Eurem neuen Zuhause. Wir wissen, dass Ihr Euch hier sehr wohlfühlen werdet, und wir freuen uns schon darauf, Euch in der Nachbarschaft zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91864] = { id = 91864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückblick: Fragmentierte Visionen", description = "Viele in ganz Azeroth hatten Visionen von einem strahlenden Gesang. Die Bemühungen, das zu verstehen, was wie eine Warnung erschien, konzentrierten sich auf die Champions in Dalaran.", sourceObjective = "Seht im Geschichtsfolianten nach, um mehr über das Schicksal Dalarans in The War Within zu erfahren.", completion = "Die Insel Khaz Algar spielte in Xal'ataths Plänen eine Rolle, und die Champions Azeroths mussten sie vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[91954] = { id = 91954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugefroren", sourceObjective = "Wir haben diesen gewaltigen Kriecher dabei beobachtet, wie er Euch draußen in der Ödnis nachstellt, aber als er sich zeigte, machte er keinerlei Anstalten, anzugreifen. Seine Reaktion auf Eure Ankunft legt nahe, dass er nach Euch gesucht hat. Ihr werdet ja richtig beliebt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[91955] = { id = 91955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur unter uns", description = "Das Artefakt, das wir uns vorhin aus der Zeitlinie gemopst haben, wurde durch ein Simulakrum ersetzt, damit niemand das Fehlen des echten Artefakts bemerkt.\n\nEine derartige Menge ewiger Macht sollten wir nicht einfach aufgeben. Ihr solltet es finden und wiederbeschaffen.\n\nSobald Ihr das Simulakrum wiederhabt, könnt Ihr es zerlegen und eine geradezu unanständige Menge Bronze und ewige Macht erhalten.", sourceObjective = "Beschafft das seltsame Simulakrum, das anstelle Eurer \"geborgten\" Artefaktwaffe zurückgelassen wurde, indem Ihr die Beschaffungsgeschichte Eurer Artefaktwaffe als Teil der Ordenshallenkampagne abschließt.", completion = "Ihr hattet Erfolg!\n\nEs ist schon fast schade, eine so schöne Replik zu zerstören.\n\nDoch Ihr habt ja jetzt das Original, also würde ich sagen, zerlegt sie und freut Euch über die Fülle bezaubernder Bronze!", sourceObjectiveStatus = "unverified-source-field" }
quests[91968] = { id = 91968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen zu Hause", description = "Wie sieht es denn hier aus? Vielleicht mussten die vorherigen Besitzer überstürzt ausziehen. Wir sollten aufräumen!\n\nDie entfernten Gegenstände wandern in die Haustruhe. Ihr könnt sie jederzeit wieder aufstellen, wenn Euch die Spinnennetze gefallen.", sourceObjective = "Hebt Objekte in Eurem Haus auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[91969] = { id = 91969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu dekorieren", description = "Jetzt ist es hier sauber und wir können dekorieren!\n\nDie Gemeinschaft hat sich mit Spenden beteiligt, damit Ihr genug Optionen zur Verfügung habt.\n\nSehen wir sie uns mal an!", sourceObjective = "Dekoriert Euer Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[92018] = { id = 92018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "x.x Testing (YGR)" }
quests[92028] = { id = 92028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschuldigt die Störung", description = "{name}! Schön, Euch zu sehen. Die Verteidiger in der Festung könnten Eure Hilfe gebrauchen.\n\nEine der Gnome hat einen Roboter gebaut, der bei der Verteidigung der Feste helfen soll. Allerdings dreht er jedes Mal durch, wenn man ihn anschaltet.\n\nSie braucht jemanden, der die Angriffe des Roboters unterbricht, damit er repariert werden kann.\n\nKönntet Ihr etwas Zeit dafür erübrigen?", sourceObjective = "Aktiviert Kampfbot 11.2.7, unterbrecht dann seine Fähigkeiten 3-mal.", progress = "Endlich ist Hilfe eingetroffen! Hoffentlich findet Ihr einen Weg, die Fähigkeiten dieses Bots zu unterbrechen.", completion = "Hervorragende Arbeit! Jetzt sollte ich Zeit haben, den Fehler zu beheben, der ursprünglich dafür verantwortlich ist.\n\nVielleicht sollte ich einfach so tun, als wäre es Absicht gewesen, und es gut sein lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[92031] = { id = 92031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft die Vandalen", description = "<Die Vandalen der Manaschmiede beim Schattenpunkt können es kaum erwarten, dass die Schattenwache und ihre Verbündeten aus der Manaschmiede Omega entfernt werden. Es ist vermutlich kein schlechter Zeitpunkt, ihnen einen Besuch abzustatten.>", sourceObjective = "Meldet Euch bei Zo'turu am Schattenpunkt.", completion = "Euer Ruf eilt Euch voraus, was das Stürzen von Tyrannen betrifft. Fügen wir dieser Liste doch einen weiteren hinzu.", sourceObjectiveStatus = "unverified-source-field" }
quests[92078] = { id = 92078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Rezept!", sourceObjective = "Da seid Ihr ja schon wieder! Ich glaube, ich habe eine Verwendung für die manageschmiedeten Instrumente gefunden, die Ihr bei Araz gefunden habt. Es handelt sich um Maschinenteile, die, wenn richtig extrahiert, ein einzigartiges Energiesignal ausgeben, dass der Magie ähnelt, mit der die Astralen gebunden werden. Wenn Ihr oder jemand, den Ihr kennt, besonders gewandt in der Verzauberkunst oder Inschriftenkunde seid, dann nehmt sie! Sie könnten Geheimnisse in sich tragen oder Euch zumindest eine neue Erfahrung bieten. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[92082] = { id = 92082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand wie ich" }
quests[92330] = { id = 92330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapferkeitssteine", sourceObjective = "Eine weitere abgeschlossene Aufgabe. Der Bund dankt Euch für Eure Mühe. Die Gründerin hat einen Fonds eingerichtet, um solches Engagement zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[92331] = { id = 92331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turboschub: Der Handel muss laufen", description = "<Die Kartelle setzen den Bund unter Druck, damit der Markt offen bleibt. Wir brauchen jemanden, der gewisse... Hindernisse aus dem Weg räumen kann. Kartell So hat die Erlaubnis, große Belohnungen auszuhändigen, falls Ihr Erfolg habt.\n\nSchließt die Aufgabe ab und holt Euch von Schmierer So'kir vor der Schatzkammer von Dornogal eine besondere Belohnung ab. Vertragspartner sind nicht an implizierte Schwüre gebunden, die im Verlauf des Handels aufkommen können. Es gelten die allgemeinen Handelsbedingungen des Mittlerkodex.>", sourceObjective = "Besiegt vier beliebige Bosse in der Manaschmiede Omega auf dem Schwierigkeitsgrad 'Normal' oder höher oder schließt vier beliebige mythische Dungeons ab.", completion = "Der Bund dankt Euch für Eure Hilfe, {name}.\n\nHier wie versprochen Eure Belohnung.\n\nUm unsere neue, erfolgreiche Partnerschaft zu feiern, erhaltet Ihr einen kleinen Leistungsbonus. Später haben wir mehr Arbeit für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[92332] = { id = 92332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turboschub: Ewiges Wachstum", description = "<Wenn der Handel weiter wachsen soll, gibt es für den Bund immer noch mehr zu tun. Ich wiederhole: Kartell So darf große Reichtümer aushändigen, wenn Ihr Erfolg habt.\n\nSchließt die Aufgabe ab und holt Euch von Schmierer So'kir vor der Schatzkammer von Dornogal eine besondere Belohnung ab. Vertragspartner sind nicht an implizierte Schwüre gebunden, die im Verlauf des Handels aufkommen können. Es gelten die allgemeinen Handelsbedingungen des Mittlerkodex.>", sourceObjective = "Besiegt vier beliebige Bosse in der Manaschmiede Omega auf dem Schwierigkeitsgrad 'Normal' oder höher oder schließt vier beliebige mythische Dungeons ab.", completion = "Der Bund dankt Euch für Eure Hilfe, {name}.\n\nHier wie versprochen Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[92405] = { id = 92405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Euch mit Arator", description = "Seid gegrüßt, Champion. Ich habe eine wichtige Nachricht für Euch von Arator. Er bittet Euch, sich ihm und seiner Tante Vereesa auf der Oztaninsel vor der Küste im Westen anzuschließen.", sourceObjective = "Sucht Arator und Vereesa Windläufer auf der Oztaninsel vor der Küste der Insel von Dorn auf.", completion = "Meine Tante wird von schrecklichen Visionen geplagt, und sie werden immer schlimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[92430] = { id = 92430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem ewigen Chaos ergeben", sourceObjective = "Sprecht mit Eternus auf dem Ewigen Basar in der Nähe von Dalaran.", completion = "Ihr kommt genau recht, {name}. Nun kann die Forschung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[92437] = { id = 92437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nStein gelegt von verlorener Hand.\nDas Schmelzwasser überbrückt.\nSucht, wo die Blumen lauschen.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[92439] = { id = 92439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Teufelsläufer", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nHier untersuchen wir das Phänomen, die Legion mit ihrer eigenen Macht zu bekämpfen, also konzentriert Euch darauf, Eure Feinde mithilfe von dämonischer Teufelsenergie zu töten.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 100 Gegner, während 'Verdrehter Kreuzzug' Eure aktive Artefaktfähigkeit ist.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[92440] = { id = 92440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Sturmläufer", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Eure Einstimmung auf den Sturm, also zeigt Euren Gegnern buchstäblich, woher der Wind weht.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 100 Gegner, während 'Sturmzorn' Eure aktive Artefaktfähigkeit ist.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[92441] = { id = 92441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Magierläufer", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Eure Einstimmung auf das Arkane, also konzentriert Euch darauf, Gegner mit mächtiger Magie zu bekämpfen.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 100 Gegner, während 'Narans Immerscheibe' Eure aktive Artefaktfähigkeit ist.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[92442] = { id = 92442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Forschung: Kampfstudien, Lichtläufer", description = "Um Eure Macht und die Eures Artefakts in dieser Zeitlinie besser zu verstehen, müssen wir Kampfstudien durchführen. Das ist so etwas wie eine Feldstudie, aber gewalttätiger.\n\nDiese Studie dreht sich um Eure Einstimmung auf das Licht, also konzentriert Euch darauf, Eure Gegner mit heiliger Gerechtigkeit niederzustrecken.\n\nUnd denkt immer daran, es ist für einen guten Zweck.", sourceObjective = "Tötet 100 Gegner, während 'Richturteil des Verteidigers' Eure aktive Artefaktfähigkeit ist.", completion = "Beeindruckend. Ich kann Eure Macht spüren. Das ist absolut unverzichtbar für unsere Forschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[92523] = { id = 92523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[92563] = { id = 92563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accessoire-Erweckung", description = "<Als Ihr das Schmuckstück ausrüstet, spürt Ihr, wie Kraft durch Euch und Eure Artefaktwaffe fließt.\n\nDas Schmuckstück hat das verborgene Potenzial Eurer Artefaktwaffe freigesetzt und einen ihrer Boni verstärkt.\n\nMoratari wird diese Daten aufzeichnen wollen.>", sourceObjective = "Sprecht mit Moratari auf dem Ewigen Basar in der Nähe von Dalaran.", completion = "Faszinierend. Es sieht so aus, als wäre Euer neues Accessoire im Stande, ansonsten unzugängliche Kräfte Eurer neuen Artefaktwaffe zu erwecken oder sie sogar über ihre eigenen Grenzen hinaus zu verbessern!\n\nIch frage mich, ob alle Schmuckstücke über diese Verbindung mit Eurer Artefaktwaffe verfügen. Haltet mich bitte auf dem Laufenden über mögliche neue Anomalien.", sourceObjectiveStatus = "unverified-source-field" }
quests[92572] = { id = 92572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausstattungsansuchen", description = "Seid gegrüßt! Wie ich sehe, habt Ihr ein Auge auf unsere schicken Möbel geworfen.\n\nMeine Geschwister und ich wurden auf eine Mission entsandt, die feinsten Dekorationen im Land zu finden.\n\nDekorationen sind mehr als nur Mobiliar, wisst Ihr. Wenn man eine wahrlich perfekte Dekoration erschaffen will, muss man auf so viele verschiedene Details achten.\n\nKommt, lasst uns gemeinsam diese Reise antreten! Wir beginnen gleich heute. Heute finden wir eine Truhe. Aber nicht irgendeine Truhe, sondern eine richtig fantastische! Eine traumhafte Truhe.\n\nIch habe gehört, so etwas kann man in der Nähe kaufen...", sourceObjective = "Kauft eine Vorratstruhe in Dornogal, Sturmwind oder Orgrimmar und kehrt zu einem der Pando-Geschwister zurück.", progress = "Wie läuft Euer Tag so? Ist er fantastisch?", completion = "Meine Güte, die Truhe, die Ihr beschrieben habt, klingt wirklich großartig. Es wird ein Riesenvergnügen, sie zu platzieren.\n\nDanke, dass Ihr sie gefunden habt. Für Eure Zeit gebe ich Euch dieses seltene Stück aus unserer Sammlung.\n\nEs ist kein gewöhnliches Fass, so viel steht fest! Ich hoffe, dass es Euch viel Freude bereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[92649] = { id = 92649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schattiger Pfad durch die Zeit", description = "Alte Gegner kehren zurück und Kampfwunden reißen erneut auf.\n\nBesiegt diese Feinde und kehrt mit ruhmreichen Geschichten zurück.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Gibt es Neues an der Front?", sourceObjectiveStatus = "unverified-source-field" }
quests[92650] = { id = 92650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die flackernde Anima", description = "Die seltsame Anima schimmert und gibt ein sanftes Summen von sich. Sie ist kaum größer als eine Kerze. Als Eure Hand sich ihr nähert, entlädt sie sich und überflutet Euren Geist mit einem Strom von Visionen. Blutige Triumphe, von Kummer erfüllte Reue, allzu flüchtige Momente der Ruhe, der bittere Geschmack von Verrat. Der unerträgliche Strom droht, Euren Verstand wie Glas zersplittern zu lassen.\n\nPlötzliche Stille. Die Visionen enden und hinterlassen ein Bild von Oribos, eingebrannt in Euren Geist.", sourceObjective = "Bringt die flackernde Anima zu Ta'steld in Oribos.", completion = "<Ta'steld nimmt die seltsame Anima und studiert den Irrwisch, der in seiner Hand tanzt.>\n\nEs war richtig, mir dies zu bringen. Als Händler verlorener Kuriositäten weiß ich genau, was damit zu tun ist. Habt Dank, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[92688] = { id = 92688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronzenes Simulakrum", description = "<Erus wird das sicher gern für Euch in einen ganzen Haufen Bronze zerlegen.>", sourceObjective = "Gebt Erus auf dem Ewigen Basar in der Nähe von Dalaran das bronzene Simulakrum.", progress = "Ihr habt etwas für Erus?", completion = "JA! Erus zerlegt!", sourceObjectiveStatus = "unverified-source-field" }
quests[92816] = { id = 92816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief voller Abenteuer", description = "<Ihr blickt nach unten und seht einen abgenutzten Brief mit Eurem Namen darauf.\n\nSeid Ihr nicht neugierig auf den Inhalt?>", sourceObjective = "Öffnet den Abenteuerbrief.", sourceObjectiveStatus = "unverified-source-field" }
quests[92855] = { id = 92855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut Ding will Eile haben", sourceObjective = "Was denn, glaubt Ihr etwa, ich schenke Euch meine Waren einfach?\n\n<Lidamorrutu grummelt.>\n\nIch schätze, das ist wohl genau das, was ich tun werde. Eternus' Befehl, irgendwas von wegen \"das Experiment beschleunigen\".\n\nWehe, Ihr verliert das. Und lasst es Erus ja nicht in die Finger bekommen.Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[92875] = { id = 92875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Krieg im Inneren verstehen", description = "Ich fürchte, Eure Zeit in Valdrakken neigt sich dem Ende zu.\n\nDunkle Mächte sammeln sich und bedrohen andere Teile Azeroths. Wir werden tun, was wir können, um Iridikrons Intrigen aufzudecken.\n\nIhr müsst mehr über die Geschehnisse erfahren.", sourceObjective = "Seht im Geschichtsfolianten in Valdrakken nach, um mehr über die Saga von The War Within zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[92961] = { id = 92961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nWache aus Stein.\nErste Begrüßung jedes Nachbarn.\nSucht im tiefsten Schatten.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[92962] = { id = 92962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nWolken beugen sich dem Stein.\nHöhen, in die sich selbst die Greifen nicht wagen.\nÜber alldem wartet es.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[92963] = { id = 92963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nWo Hochlandfrost auf Nebel trifft.\nDas Tor zum düsteren Wald.\nDie Gefallenen weisen den Weg.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
